void PartTest::testSameFileSaveIgnoresOwnWatcherEvents()
{
    class SetupObserver final : public Okular::DocumentObserver
    {
    public:
        void notifySetup(const QList<Okular::Page *> &, int setupFlags) override
        {
            if (setupFlags & Okular::DocumentObserver::DocumentChanged) {
                ++documentChangedCount;
            }
            if (setupFlags & Okular::DocumentObserver::UrlChanged) {
                ++urlChangedCount;
            }
        }

        int documentChangedCount = 0;
        int urlChangedCount = 0;
    };

    const QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    const QString pdfPath = QDir(temporaryDirectory.path()).filePath(QStringLiteral("open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));

    Okular::Part part(nullptr, {});
    QVERIFY(openDocument(&part, pdfPath));
    SetupObserver observer;
    part.m_document->addObserver(&observer);
    observer.documentChangedCount = 0;
    observer.urlChangedCount = 0;

    auto *annotation = new Okular::TextAnnotation();
    annotation->setTextType(Okular::TextAnnotation::Linked);
    annotation->setBoundingRectangle(Okular::NormalizedRect(0.1, 0.1, 0.2, 0.2));
    annotation->setContents(QStringLiteral("watcher regression"));
    part.m_document->addPageAnnotation(0, annotation);
    const Okular::Page *const pageBeforeSave = part.m_document->page(0);
    const QString annotationName = annotation->uniqueName();

    // Simulate an already queued dirty notification from before save.
    part.m_dirtyHandler->start(750);
    QVERIFY(part.m_dirtyHandler->isActive());

    QVERIFY(part.saveAs(QUrl::fromLocalFile(pdfPath)));
    QCOMPARE(observer.documentChangedCount, 0);
    QCOMPARE(observer.urlChangedCount, 0);
    QCOMPARE(part.m_document->page(0), pageBeforeSave);
    QCOMPARE(part.m_document->page(0)->annotation(annotationName), annotation);
    QVERIFY(part.m_document->isHistoryClean());
    QCOMPARE(part.m_document->documentInfo().get(Okular::DocumentInfo::DocumentSize), KFormat().formatByteSize(QFileInfo(pdfPath).size()));
    QVERIFY(!part.m_dirtyHandler->isActive());
    QVERIFY(part.m_ignoreDirtySignalsForCurrentRevision);
    QTest::qWait(900);
    QCOMPARE(observer.documentChangedCount, 0);
    QCOMPARE(observer.urlChangedCount, 0);

    const QString revisedContents = QStringLiteral("watcher regression revised");
    part.m_document->editPageAnnotationContents(0, annotation, revisedContents, revisedContents.size(), annotation->contents().size(), annotation->contents().size());
    QVERIFY(part.saveAs(QUrl::fromLocalFile(pdfPath)));
    QCOMPARE(observer.documentChangedCount, 0);
    QCOMPARE(observer.urlChangedCount, 0);
    QCOMPARE(part.m_document->page(0), pageBeforeSave);
    QCOMPARE(part.m_document->page(0)->annotation(annotationName), annotation);
    QCOMPARE(annotation->contents(), revisedContents);
    const QString persistedPdfPath = QDir(temporaryDirectory.path()).filePath(QStringLiteral("persisted.pdf"));
    QVERIFY(QFile::copy(pdfPath, persistedPdfPath));

    // KDirWatch may emit more than one event for an atomic replacement. All
    // events for the exact revision Okular wrote must be consumed.
    part.slotFileDirty(pdfPath);
    part.slotFileDirty(QFileInfo(pdfPath).absolutePath());
    QVERIFY(!part.m_dirtyHandler->isActive());

    // A genuinely different on-disk revision must still arm normal reload.
    QFile changedPdf(pdfPath);
    QVERIFY(changedPdf.open(QIODevice::Append));
    QCOMPARE(changedPdf.write("x", 1), 1);
    changedPdf.close();
    part.slotFileDirty(pdfPath);
    QVERIFY(part.m_dirtyHandler->isActive());
    QVERIFY(!part.m_ignoreDirtySignalsForCurrentRevision);
    part.m_dirtyHandler->stop();
    part.m_document->removeObserver(&observer);

    Okular::Part reopenedPart(nullptr, {});
    QVERIFY(openDocument(&reopenedPart, persistedPdfPath));
    Okular::Annotation *const persistedAnnotation = reopenedPart.m_document->page(0)->annotation(annotationName);
    QVERIFY(persistedAnnotation);
    QCOMPARE(persistedAnnotation->contents(), revisedContents);
}

void PartTest::testBackingFileRefreshDoesNotShowLoadedMessage()
{
    Okular::Part part(nullptr, {});
    QVERIFY(openDocument(&part, QStringLiteral(KDESRCDIR "data/file2.pdf")));
    QCOMPARE(part.m_document->pages(), 2u);

    const auto labels = part.m_pageView->findChildren<QLabel *>();
    for (QLabel *label : labels) {
        if (label->text().contains(QStringLiteral("Loaded"))) {
            label->clear();
        }
    }

    // Force the non-reuse branch while still identifying this as a backing
    // file refresh. Before the regression fix, PageView promoted its local
    // mismatch to "document changed" and displayed a false Loaded banner.
    QList<Okular::Page *> refreshedPages {
        const_cast<Okular::Page *>(part.m_document->page(1)),
        const_cast<Okular::Page *>(part.m_document->page(0)),
    };
    part.m_pageView->notifySetup(refreshedPages, Okular::DocumentObserver::UrlChanged);

    for (QLabel *label : part.m_pageView->findChildren<QLabel *>()) {
        QVERIFY2(!label->text().contains(QStringLiteral("Loaded")), qPrintable(label->text()));
    }
}

void PartTest::testDocsCommentSyncInvalidPlacementIsNonfatal()
{
    QTemporaryDir temp;
    QVERIFY(temp.isValid());
    QDir root(temp.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), root.filePath(QStringLiteral("current_pdfs/open.pdf"))));
    QFile sidecar(root.filePath(QStringLiteral("comments/open_comments.jsonl")));
    QVERIFY(sidecar.open(QIODevice::WriteOnly));
    const QJsonObject bad{{QStringLiteral("id"), QStringLiteral("bad-placement")},
        {QStringLiteral("page"), 1}, {QStringLiteral("subtype"), QStringLiteral("Text")},
        {QStringLiteral("contents"), QStringLiteral("Keep this comment")},
        {QStringLiteral("rect"), QJsonArray{10, 20}}};
    sidecar.write(QJsonDocument(bad).toJson(QJsonDocument::Compact) + '\n');
    sidecar.close();
    DocsCommentSynchronizer sync({.docsRoot = temp.path(), .processEnvironment = QProcessEnvironment::systemEnvironment()});
    auto result = sync.prepareSidecar(QStringLiteral("open"), [](const QString &, int, QString *) {
        return std::optional<DocsCommentSynchronizer::PageGeometry>({612.0, 792.0, 0});
    });
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QVERIFY(result.logLines.join(QLatin1Char('\n')).contains(QStringLiteral("bad-placement")));
    QVERIFY(sidecar.open(QIODevice::ReadOnly));
    const auto retained = sidecar.readAll();
    QVERIFY(retained.contains("Keep this comment"));
    QVERIFY(retained.contains("invalid_pdf_placement"));
    QVERIFY(!retained.contains("\"deleted\":true"));
}

void PartTest::testDocsCommentSyncPathDetection()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    const QString pdf = QStringLiteral(KDESRCDIR "data/file1.pdf");
    QVERIFY(addLibraryPdf(docsRoot.path(), pdf, QStringLiteral("manual.pdf")));
    // Same filename outside current_pdfs/, and an unregistered Library PDF.
    for (const QString &copy : {QStringLiteral("incoming_pdfs/manual.pdf"), QStringLiteral("current_pdfs/nested/manual.pdf"), QStringLiteral("third_party/manual.pdf")}) {
        QVERIFY(root.mkpath(QFileInfo(root.filePath(copy)).path()));
        QVERIFY(QFile::copy(pdf, root.filePath(copy)));
    }
    QVERIFY(QFile::copy(pdf, root.filePath(QStringLiteral("current_pdfs/unregistered.pdf"))));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();

    QVERIFY(part.shouldSyncDocsComments(QUrl::fromLocalFile(QDir(docsRoot.path()).filePath(QStringLiteral("current_pdfs/manual.pdf")))));
    QVERIFY(!part.shouldSyncDocsComments(QUrl::fromLocalFile(QDir(docsRoot.path()).filePath(QStringLiteral("current_pdfs/unregistered.pdf")))));
    QVERIFY(!part.shouldSyncDocsComments(QUrl::fromLocalFile(QDir(docsRoot.path()).filePath(QStringLiteral("incoming_pdfs/manual.pdf")))));
    QVERIFY(!part.shouldSyncDocsComments(QUrl::fromLocalFile(QDir(docsRoot.path()).filePath(QStringLiteral("current_pdfs/nested/manual.pdf")))));
    QVERIFY(!part.shouldSyncDocsComments(QUrl::fromLocalFile(QDir(docsRoot.path()).filePath(QStringLiteral("third_party/manual.pdf")))));
    QVERIFY(!part.shouldSyncDocsComments(QUrl::fromLocalFile(docsRoot.path() + QStringLiteral("-copy/current_pdfs/manual.pdf"))));
    QVERIFY(!part.shouldSyncDocsComments(QUrl(QStringLiteral("https://example.com/manual.pdf"))));
}

// A version opened from a card's History (PdfVersions cache) is never a Library document, even
// with the bytes of a Library PDF: no comment sync, no annotations; its passage can be shown.
void PartTest::testEarlierPdfVersionIsAPlainReadOnlyPdf()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    const QString pdf = QStringLiteral(KDESRCDIR "data/file1.pdf");
    QVERIFY(addLibraryPdf(docsRoot.path(), pdf, QStringLiteral("manual.pdf")));
    QFile source(pdf);
    QVERIFY(source.open(QIODevice::ReadOnly));
    const QByteArray bytes = source.readAll();
    const QString digest = QString::fromLatin1(QCryptographicHash::hash(bytes, QCryptographicHash::Sha256).toHex());
    // The default cache, under this test's own HOME.
    const QString cached = Thoughts::PdfVersions::store(Thoughts::PdfVersions::defaultCacheRoot(), digest, bytes);
    QVERIFY(!cached.isEmpty());
    auto removeCached = qScopeGuard([&cached] { QFile::remove(cached); });
    QVERIFY(Thoughts::PdfVersions::isCachedVersion(cached));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    const QUrl url = QUrl::fromLocalFile(cached);
    QVERIFY(part.shouldSyncDocsComments(QUrl::fromLocalFile(QDir(docsRoot.path()).filePath(QStringLiteral("current_pdfs/manual.pdf")))));
    QVERIFY(!part.shouldSyncDocsComments(url));
    QVERIFY(!part.isWorkspaceThirdPartyPdf(url));
    QVERIFY(Thoughts::DocumentIdentityStore(docsRoot.path()).forFile(cached).isEmpty());

    QVERIFY(openDocument(&part, cached));
    QVERIFY(!part.m_document->isAllowed(Okular::AllowNotes));
    QVERIFY(!part.isModified());
    QCOMPARE(part.m_document->pages(), 1u);
    // The feedback's passage is marked like a selection, and nothing is written for it.
    QVERIFY(part.showPassageRegions({QVariantMap{{QStringLiteral("page"), 1}, {QStringLiteral("rect"), QVariantList{0.05, 0.05, 0.9, 0.2}}}}));
    QVERIFY(part.m_document->page(0)->textSelection());
    QVERIFY(!part.isModified());
    QVERIFY(!QFileInfo::exists(QDir(docsRoot.path()).filePath(QStringLiteral("comments"))));
    QCOMPARE(QDir(QFileInfo(cached).absolutePath()).entryList(QDir::Files), QStringList{QFileInfo(cached).fileName()});
    part.closeUrl();
}

// "Show history" of a card under review: the sidebar shows, on History.
