void PartTest::testDocsCommentSyncAfterSave()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    QFile phoneSidecar(root.filePath(QStringLiteral("comments/open_comments.jsonl")));
    QVERIFY(phoneSidecar.open(QIODevice::WriteOnly | QIODevice::Text));
    const QByteArray phoneRecord =
        "{\"schema_version\":5,\"id\":\"phone-parent\",\"revision\":6,"
        "\"updated_at\":\"2026-07-25T09:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":1,\"subtype\":\"Text\",\"rect\":[5,6,7,8],"
        "\"contents\":\"phone parent\",\"created_in_app\":\"mj-pdf-reader\"}\n"
        "{\"schema_version\":5,\"id\":\"phone-only\",\"revision\":7,"
        "\"updated_at\":\"2026-07-25T10:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":1,\"subtype\":\"Text\",\"rect\":[1,2,3,4],"
        "\"contents\":\"written on the phone\",\"in_reply_to\":\"phone-parent\","
        "\"created_in_app\":\"mj-pdf-reader\"}\n";
    QCOMPARE(phoneSidecar.write(phoneRecord), phoneRecord.size());
    phoneSidecar.close();

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(openDocument(&part, pdfPath));
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 3000);

    auto *annotation = new Okular::TextAnnotation();
    annotation->setTextType(Okular::TextAnnotation::Linked);
    annotation->setBoundingRectangle(Okular::NormalizedRect(0.1, 0.2, 0.2, 0.3));
    annotation->setContents(QStringLiteral("snapshot comment"));
    part.m_document->addPageAnnotation(0, annotation);

    auto *highlight = new Okular::HighlightAnnotation();
    highlight->setHighlightType(Okular::HighlightAnnotation::Highlight);
    highlight->setBoundingRectangle(Okular::NormalizedRect(0.1, 0.2, 0.4, 0.3));
    highlight->setContents(QStringLiteral("snapshot markup"));
    Okular::HighlightAnnotation::Quad quad;
    quad.setPoint(Okular::NormalizedPoint(0.1, 0.3), 0);
    quad.setPoint(Okular::NormalizedPoint(0.4, 0.3), 1);
    quad.setPoint(Okular::NormalizedPoint(0.4, 0.2), 2);
    quad.setPoint(Okular::NormalizedPoint(0.1, 0.2), 3);
    highlight->highlightQuads().append(quad);
    part.m_document->addPageAnnotation(0, highlight);

    // Library PDFs are immutable, so explicit synchronization replaces the
    // former save-time synchronization into the managed PDF.
    const QVariantMap synchronized = part.synchronizeDocsCommentsNow();
    QVERIFY2(synchronized.value(QStringLiteral("success")).toBool(), qPrintable(synchronized.value(QStringLiteral("error")).toString()));

    QFile comments(root.filePath(QStringLiteral("comments/open_comments.jsonl")));
    QVERIFY(comments.open(QIODevice::ReadOnly));
    const QByteArray savedComments = comments.readAll();
    QCOMPARE(savedComments.count('\n'), 4);
    QVERIFY(savedComments.contains("\"contents\":\"snapshot comment\""));
    QVERIFY(savedComments.contains("\"contents\":\"snapshot markup\""));
    QVERIFY(savedComments.contains("\"contents\":\"phone parent\""));
    QVERIFY(savedComments.contains("\"contents\":\"written on the phone\""));
    QVERIFY(savedComments.contains("\"in_reply_to\":\"phone-parent\""));
    QCOMPARE(savedComments.count("\"created_in_app\":\"mj-pdf-reader\""), 2);
    QVERIFY2(savedComments.contains("\"origin_id\":\"android-mj-pdf\""), savedComments.constData());
    QVERIFY(savedComments.contains("\"revision\":7"));
    QVERIFY(savedComments.contains("\"anchor_status\":\"needs_anchor\""));
    QVERIFY(!QFileInfo::exists(root.filePath(QStringLiteral("comments/.base/open_comments.jsonl"))));
    QVERIFY(QFileInfo::exists(root.filePath(QStringLiteral("comments/.state/open.json"))));
    QFile log(part.m_docsCommentSyncLogPath);
    QVERIFY(log.open(QIODevice::ReadOnly));
    QVERIFY(log.readAll().contains("native synchronization"));
}

void PartTest::testCompilerCommentFixtureProjection()
{
    QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    QDir root(temporary.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString path = root.filePath(QStringLiteral("current_pdfs/manual.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/compiler-comments/corpus.pdf"), path));
    QVERIFY(registerLibraryPdf(root.path(), path));
    QFile input(QStringLiteral(KDESRCDIR "data/compiler-comments/artifact.json"));
    QVERIFY(input.open(QIODevice::ReadOnly));
    const QByteArray original = input.readAll();
    const QJsonObject manifest = QJsonDocument::fromJson(original).object();
    QFile expectedFile(QStringLiteral(KDESRCDIR "data/compiler-comments/expectations.json"));
    QVERIFY(expectedFile.open(QIODevice::ReadOnly));
    const QJsonObject expected = QJsonDocument::fromJson(expectedFile.readAll()).object();
    QCOMPARE(QString::fromLatin1(QCryptographicHash::hash(original, QCryptographicHash::Sha256).toHex()), expected.value(QStringLiteral("artifact_sha256")).toString());
    QFile pdfFile(path);
    QVERIFY(pdfFile.open(QIODevice::ReadOnly));
    const QString pdfHash = QString::fromLatin1(QCryptographicHash::hash(pdfFile.readAll(), QCryptographicHash::Sha256).toHex());
    QCOMPARE(pdfHash, expected.value(QStringLiteral("pdf_sha256")).toString());
    const QDir bundle(QDir(QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)).filePath(QStringLiteral("thoughts-server/source-bundle")));
    QVERIFY(QDir().mkpath(bundle.filePath(QStringLiteral("documents"))));
    QVERIFY(QDir().mkpath(bundle.filePath(QStringLiteral("objects"))));
    const QString pointerPath = bundle.filePath(QStringLiteral("documents/manual.pdf.json"));
    QFile previous(pointerPath);
    const bool hadPointer = previous.exists();
    QByteArray oldPointer;
    if (previous.open(QIODevice::ReadOnly)) oldPointer = previous.readAll();
    previous.close();
    QStringList created;
    const auto cleanup = qScopeGuard([&] {
        if (hadPointer) { QFile restore(pointerPath); if (restore.open(QIODevice::WriteOnly | QIODevice::Truncate)) restore.write(oldPointer); }
        else QFile::remove(pointerPath);
        for (const QString &file : std::as_const(created)) QFile::remove(file);
    });
    const auto publish = [&](const QByteArray &raw) {
        const QString hash = QString::fromLatin1(QCryptographicHash::hash(raw, QCryptographicHash::Sha256).toHex());
        const QString objectPath = bundle.filePath(QStringLiteral("objects/") + hash);
        if (!QFileInfo::exists(objectPath)) {
            QFile object(objectPath);
            if (!object.open(QIODevice::WriteOnly) || object.write(raw) != raw.size()) return false;
            created.append(objectPath);
        }
        QFile pointer(pointerPath);
        return pointer.open(QIODevice::WriteOnly | QIODevice::Truncate)
            && pointer.write(QJsonDocument(QJsonObject {{QStringLiteral("schema_version"), 1}, {QStringLiteral("artifact_sha256"), hash}}).toJson()) > 0;
    };
    QVERIFY(publish(original));
    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = temporary.path();
    QVERIFY(openDocument(&part, path));
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 3000);
    for (const QJsonValue &value : manifest.value(QStringLiteral("logical_comments")).toArray()) {
        QJsonObject payload = value.toObject();
        const QString id = payload.value(QStringLiteral("comment_id")).toString();
        if (id == QLatin1String("cell")) {
            payload.insert(QStringLiteral("contents"), QStringLiteral("Latest local cell edit"));
            payload.insert(QStringLiteral("revision"), 8);
        }
        part.m_fedoraProjections.insert(QStringLiteral("logical_comment\ncomments\n") + id, payload);
    }
    const auto refresh = [&] {
        part.m_hasFedoraProjectionSnapshot = true;
        part.m_docsUseFedoraForNextCommentRefresh = true;
        part.refreshDocsCommentsFromSidecar();
    };
    refresh();
    QCOMPARE(part.m_docsCommentRecords.size(), manifest.value(QStringLiteral("logical_comments")).toArray().size());
    const QJsonObject cell = part.m_docsCommentRecords.value(QStringLiteral("cell"));
    QCOMPARE(cell.value(QStringLiteral("contents")).toString(), QStringLiteral("Latest local cell edit"));
    QCOMPARE(cell.value(QStringLiteral("quad_points")).toArray().size(), 16); // Both words, not just the first same-page fragment.
    const QJsonObject pages = expected.value(QStringLiteral("point_pages")).toObject();
    for (auto it = pages.begin(); it != pages.end(); ++it) QCOMPARE(part.m_docsCommentRecords.value(it.key()).value(QStringLiteral("page")).toInt(), it.value().toInt());
    QVERIFY(part.m_docsCommentRecords.value(QStringLiteral("point-a")).value(QStringLiteral("rect")) != part.m_docsCommentRecords.value(QStringLiteral("point-b")).value(QStringLiteral("rect")));
    QVERIFY(!part.isModified());

    // The same source-produced native markers are used for first-open navigation.
    part.m_docsCommentRefreshQueued = true;
    QVERIFY(part.openReviewAnnotation(QStringLiteral("float"), 3));
    refresh();
    QTRY_VERIFY_WITH_TIMEOUT(part.m_pendingReviewAnnotationId.isEmpty(), 2000);
    QCOMPARE(part.m_document->viewport().pageNumber, 2);

    QJsonObject reply = part.m_fedoraProjections.value(QStringLiteral("logical_comment\ncomments\ncell")).toObject();
    reply.insert(QStringLiteral("comment_id"), QStringLiteral("reply"));
    reply.insert(QStringLiteral("parent_id"), QStringLiteral("cell"));
    reply.insert(QStringLiteral("contents"), QStringLiteral("Reply from Mobile"));
    part.m_fedoraProjections.insert(QStringLiteral("logical_comment\ncomments\nreply"), reply);
    refresh();
    QCOMPARE(part.m_docsCommentRecords.value(QStringLiteral("reply")).value(QStringLiteral("fragments")), cell.value(QStringLiteral("fragments")));

    // Native export must use this same resolved view, including every word and reply.
    const QString exportedPath = root.filePath(QStringLiteral("compiler-export.pdf"));
    const int historyBeforeExport = part.m_document->undoHistoryIndex();
    QVERIFY(part.exportPdfWithComments(QUrl::fromLocalFile(exportedPath)));
    QCOMPARE(part.m_document->undoHistoryIndex(), historyBeforeExport);
    QVERIFY(!part.isModified());
    {
        QFile unchanged(path);
        QVERIFY(unchanged.open(QIODevice::ReadOnly));
        QCOMPARE(QString::fromLatin1(QCryptographicHash::hash(unchanged.readAll(), QCryptographicHash::Sha256).toHex()), pdfHash);
        Okular::Part exported(nullptr, {});
        QVERIFY(openDocument(&exported, exportedPath));
        Okular::HighlightAnnotation *exportedCell = nullptr;
        for (Okular::Annotation *annotation : exported.m_document->page(0)->annotations()) {
            if (annotation->uniqueName() == QLatin1String("cell")) exportedCell = dynamic_cast<Okular::HighlightAnnotation *>(annotation);
        }
        QVERIFY(exportedCell);
        QCOMPARE(exportedCell->contents(), QStringLiteral("Latest local cell edit"));
        QCOMPARE(exportedCell->highlightQuads().size(), 2);
        QVERIFY(std::any_of(exported.m_document->page(2)->annotations().cbegin(), exported.m_document->page(2)->annotations().cend(),
                            [](const Okular::Annotation *annotation) { return annotation->uniqueName() == QLatin1String("float"); }));
    }

    // Invalid proof rejects the whole root, including both words, without hiding unrelated notes.
    QJsonObject bad = manifest;
    QJsonArray correspondences = bad.value(QStringLiteral("review_correspondences")).toArray();
    for (qsizetype i = 0; i < correspondences.size(); ++i) {
        QJsonObject correspondence = correspondences.at(i).toObject();
        if (correspondence.value(QStringLiteral("item_id")).toString() != QLatin1String("cell")) continue;
        QJsonArray locations = correspondence.value(QStringLiteral("locations")).toArray();
        QJsonObject location = locations.last().toObject();
        QJsonObject proof = location.value(QStringLiteral("proof")).toObject();
        proof.insert(QStringLiteral("source_sha256"), QString(64, QLatin1Char('f')));
        location.insert(QStringLiteral("proof"), proof); locations[locations.size()-1] = location;
        correspondence.insert(QStringLiteral("locations"), locations); correspondences[i] = correspondence;
    }
    bad.insert(QStringLiteral("review_correspondences"), correspondences);
    QVERIFY(publish(QJsonDocument(bad).toJson(QJsonDocument::Compact)));
    refresh();
    QVERIFY(!part.m_docsCommentRecords.contains(QStringLiteral("cell")));
    QVERIFY(!part.m_docsCommentRecords.contains(QStringLiteral("reply")));
    QVERIFY(part.m_docsCommentRecords.contains(QStringLiteral("float")));
    QVERIFY(publish(original));
    QJsonObject deleted = part.m_fedoraProjections.value(QStringLiteral("logical_comment\ncomments\ncell")).toObject();
    deleted.insert(QStringLiteral("deleted"), true);
    deleted.insert(QStringLiteral("revision"), 9);
    part.m_fedoraProjections.insert(QStringLiteral("logical_comment\ncomments\ncell"), deleted);
    refresh();
    QVERIFY(!part.m_docsCommentRecords.contains(QStringLiteral("cell")));
    QVERIFY(!part.m_docsCommentRecords.contains(QStringLiteral("reply")));
    QVERIFY(!part.isModified());
}

void PartTest::testDocsCommentUsesVerifiedPointForOpenedPdf()
{
    QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    QDir root(temporary.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString filename = QStringLiteral("verified-comment-point.pdf");
    const QString path = root.filePath(QStringLiteral("current_pdfs/") + filename);
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/simple-multipage.pdf"), path));
    QVERIFY(registerLibraryPdf(root.path(), path));
    QFile pdfFile(path);
    QVERIFY(pdfFile.open(QIODevice::ReadOnly));
    const QString digest = QString::fromLatin1(QCryptographicHash::hash(pdfFile.readAll(), QCryptographicHash::Sha256).toHex());
    pdfFile.close();
    const QDir bundle(QDir(QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)).filePath(QStringLiteral("thoughts-server/source-bundle")));
    QVERIFY(QDir().mkpath(bundle.filePath(QStringLiteral("documents"))));
    QVERIFY(QDir().mkpath(bundle.filePath(QStringLiteral("objects"))));
    const QString pointerPath = bundle.filePath(QStringLiteral("documents/") + filename + QStringLiteral(".json"));
    QStringList artifacts;
    const auto cleanup = qScopeGuard([&] {
        QFile::remove(pointerPath);
        for (const QString &artifact : std::as_const(artifacts)) {
            QFile::remove(artifact);
        }
    });
    const auto publishPoint = [&](const QString &pdfDigest, int pageNumber, double y, bool verified = true) {
        const QJsonObject location {{QStringLiteral("pdf_filename"), filename}, {QStringLiteral("pdf_sha256"), pdfDigest},
                                    {QStringLiteral("page"), pageNumber}, {QStringLiteral("point"), QJsonArray {0.5, y}},
                                    {QStringLiteral("placement_kind"), QStringLiteral("exact_point")},
                                    {QStringLiteral("proof"), QJsonObject {{QStringLiteral("verified"), verified}, {QStringLiteral("pdf_sha256"), pdfDigest}}}};
        const QJsonObject correspondence {{QStringLiteral("kind"), QStringLiteral("comment")}, {QStringLiteral("item_id"), QStringLiteral("dpo-note")},
                                          {QStringLiteral("state"), QStringLiteral("exact_point")}, {QStringLiteral("lifecycle"), QStringLiteral("active")},
                                          {QStringLiteral("locations"), QJsonArray {location}}};
        const QJsonObject manifest {{QStringLiteral("kind"), QStringLiteral("thoughts-document-source-artifact")},
                                    {QStringLiteral("pdf"), QJsonObject {{QStringLiteral("filename"), filename}, {QStringLiteral("pdf_sha256"), pdfDigest}}},
                                    {QStringLiteral("review_correspondence_schema_version"), 2},
                                    {QStringLiteral("review_correspondences"), QJsonArray {correspondence}}};
        const QByteArray raw = QJsonDocument(manifest).toJson(QJsonDocument::Compact);
        const QString artifactDigest = QString::fromLatin1(QCryptographicHash::hash(raw, QCryptographicHash::Sha256).toHex());
        const QString artifactPath = bundle.filePath(QStringLiteral("objects/") + artifactDigest);
        artifacts.append(artifactPath);
        QFile artifact(artifactPath);
        if (!artifact.open(QIODevice::WriteOnly) || artifact.write(raw) != raw.size()) {
            return false;
        }
        artifact.close();
        QFile pointer(pointerPath);
        return pointer.open(QIODevice::WriteOnly | QIODevice::Truncate)
            && pointer.write(QJsonDocument(QJsonObject {{QStringLiteral("schema_version"), 1}, {QStringLiteral("artifact_sha256"), artifactDigest}}).toJson()) > 0;
    };
    QVERIFY(publishPoint(digest, 3, 0.2));
    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = temporary.path();
    QVERIFY(openDocument(&part, path));
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 3000);
    QJsonObject record {{QStringLiteral("id"), QStringLiteral("dpo-note")}, {QStringLiteral("page"), 2},
                        {QStringLiteral("subtype"), QStringLiteral("Text")}, {QStringLiteral("rect"), QJsonArray {60, 60, 80, 80}},
                        {QStringLiteral("contents"), QStringLiteral("Current comment text")}, {QStringLiteral("revision"), 3}};
    const QString key = QStringLiteral("annotation\nverified-comment-point\ndpo-note");
    const auto refresh = [&] {
        part.m_hasFedoraProjectionSnapshot = true;
        part.m_fedoraProjections.insert(key, record);
        part.m_fedoraProjections.insert(QStringLiteral("logical_comment\ncomments\ndpo-note"),
            Internal::logicalCommentForNewPlacement(record, QStringLiteral("verified-comment-point")));
        part.m_docsUseFedoraForNextCommentRefresh = true;
        part.refreshDocsCommentsFromSidecar();
    };
    refresh();
    QCOMPARE(part.m_document->page(1)->annotations().size(), 0);
    QCOMPARE(part.m_document->page(2)->annotations().size(), 1);
    auto *annotation = part.m_document->page(2)->annotations().constFirst();
    QVERIFY(qAbs(annotation->boundingRectangle().left - 0.5) < 0.0001);
    QVERIFY(qAbs(annotation->boundingRectangle().top - 0.2) < 0.0001);
    QCOMPARE(annotation->contents(), QStringLiteral("Current comment text"));
    QVERIFY(!part.isModified());

    // A new placement must move the existing marker even when its content
    // revision and the underlying PDF remain unchanged.
    QVERIFY(publishPoint(digest, 1, 0.4));
    refresh();
    QCOMPARE(part.m_document->page(2)->annotations().size(), 0);
    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    QVERIFY(qAbs(part.m_document->page(0)->annotations().constFirst()->boundingRectangle().top - 0.4) < 0.0001);

    // Geometry for another PDF, or unverified geometry, must not be applied.
    QVERIFY(publishPoint(QString(64, QLatin1Char('a')), 3, 0.2));
    refresh();
    QCOMPARE(part.m_document->page(0)->annotations().size(), 0);
    QCOMPARE(part.m_document->page(1)->annotations().size(), 0);
    QVERIFY(publishPoint(digest, 3, 0.2, false));
    refresh();
    QCOMPARE(part.m_document->page(1)->annotations().size(), 0);
    QCOMPARE(part.m_document->page(2)->annotations().size(), 0);

    QVERIFY(publishPoint(digest, 3, 0.2));
    record.insert(QStringLiteral("deleted"), true);
    refresh();
    QCOMPARE(part.m_document->page(1)->annotations().size(), 0);
    QCOMPARE(part.m_document->page(2)->annotations().size(), 0);
    QVERIFY(!part.isModified());
}

void PartTest::testDocsCommentSidecarRefreshInPlace()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(openDocument(&part, pdfPath));
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 2000);
    QTRY_VERIFY_WITH_TIMEOUT(!part.m_docsCommentFingerprint.isEmpty(), 3000);
    QCOMPARE(part.m_document->page(0)->annotations().size(), 0);
    const QUrl originalUrl = part.m_document->currentDocument();
    QSignalSpy mimeTypeChangedSpy(&part, &Okular::Part::mimeTypeChanged);

    const auto writeFile = [](const QString &path, const QByteArray &contents) {
        QFile file(path);
        return file.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text) && file.write(contents) == contents.size();
    };
    const QString sidecarPath = root.filePath(QStringLiteral("comments/open_comments.jsonl"));
    const QByteArray first =
        "{\"schema_version\":5,\"id\":\"phone-note\",\"revision\":1,"
        "\"updated_at\":\"2026-07-25T10:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":1,\"subtype\":\"Text\",\"rect\":[60,60,120,120],"
        "\"author\":\"Phone author\",\"created\":\"D:20260725090000+02'00'\","
        "\"modified\":\"D:20260725090100\",\"contents\":\"phone text\","
        "\"flags\":4,\"opacity\":1,\"created_in_app\":\"mj-pdf-reader\"}\n";
    QVERIFY(writeFile(sidecarPath, first));
    // The test supplies the canonical comments; keep repository snapshots from replacing them.
    QVERIFY(QObject::disconnect(part.m_fedoraRepository, SIGNAL(projectionsChanged(QJsonObject, qint64)), &part, nullptr));
    part.m_hasFedoraProjectionSnapshot = true;
    addLogicalComments(part.m_fedoraProjections, pdfPath, first);
    part.refreshDocsCommentsFromSidecar();

    QCOMPARE(part.m_document->currentDocument(), originalUrl);
    QCOMPARE(mimeTypeChangedSpy.count(), 0);
    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    Okular::Annotation *const phoneAnnotation = part.m_document->page(0)->annotations().constFirst();
    QCOMPARE(phoneAnnotation->contents(), QStringLiteral("phone text"));
    QCOMPARE(phoneAnnotation->author(), QStringLiteral("Phone author"));
    QCOMPARE(phoneAnnotation->creatorApplication(), QStringLiteral("mj-pdf-reader"));
    QVERIFY(phoneAnnotation->creationDate().isValid());
    QCOMPARE(phoneAnnotation->creationDate().toUTC(), QDateTime(QDate(2026, 7, 25), QTime(7, 0), QTimeZone::UTC));
    QVERIFY(phoneAnnotation->modificationDate().isValid());
    QVERIFY(!part.isModified());

    const QByteArray edited =
        "{\"schema_version\":5,\"id\":\"phone-note\",\"revision\":2,"
        "\"updated_at\":\"2026-07-25T10:01:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":1,\"subtype\":\"Text\",\"rect\":[60,60,120,120],"
        "\"author\":\"Phone author\",\"created\":\"D:20260725090000+02'00'\","
        "\"modified\":\"D:20260725090200+02'00'\",\"contents\":\"phone text edited\","
        "\"flags\":4,\"opacity\":1,\"created_in_app\":\"mj-pdf-reader\"}\n";
    QVERIFY(writeFile(sidecarPath, edited));
    addLogicalComments(part.m_fedoraProjections, pdfPath, edited);
    part.refreshDocsCommentsFromSidecar();
    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    QCOMPARE(part.m_document->page(0)->annotations().constFirst()->contents(), QStringLiteral("phone text edited"));
    QVERIFY(!part.isModified());

    // A deletion arriving while the PDF has unsaved edits waits for a clean document.
    QByteArray deleted = edited;
    deleted.replace("\"revision\":2,", "\"revision\":3,\"deleted\":true,");
    part.setModified(true);
    QVERIFY(writeFile(sidecarPath, deleted));
    addLogicalComments(part.m_fedoraProjections, pdfPath, deleted);
    part.refreshDocsCommentsFromSidecar();
    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    QVERIFY(part.m_docsCommentRefreshQueued);
    part.setModified(false);
    QTRY_COMPARE_WITH_TIMEOUT(part.m_document->page(0)->annotations().size(), 0, 5000);
    QTRY_VERIFY_WITH_TIMEOUT(!part.m_docsCommentRefreshQueued, 5000);
    QCOMPARE(part.m_document->currentDocument(), originalUrl);
    QCOMPARE(mimeTypeChangedSpy.count(), 0);
    QVERIFY(!part.isModified());
}

void PartTest::testDocsCommentReplyThreadRefresh()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/simple-multipage.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(QMetaObject::invokeMethod(part.m_pageView, "setDocsRoot", Q_ARG(QString, docsRoot.path())));
    QVERIFY(openDocument(&part, pdfPath));
    part.widget()->resize(900, 800);
    part.widget()->show();

    QByteArray sidecar =
        "{\"schema_version\":5,\"id\":\"root\",\"revision\":1,"
        "\"updated_at\":\"2026-08-10T10:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":3,\"subtype\":\"Text\",\"rect\":[60,60,120,120],"
        "\"author\":\"Root author\",\"created\":\"D:20260810080000Z\","
        "\"modified\":\"D:20260810100000Z\",\"contents\":\"This allows us to determine what an irrecoverable error really looks like.\",\"flags\":4}\n"
        "{\"schema_version\":5,\"id\":\"reply-one\",\"in_reply_to\":\"root\",\"revision\":1,"
        "\"updated_at\":\"2026-08-10T11:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":4,\"subtype\":\"Text\",\"rect\":[60,60,120,120],"
        "\"author\":\"Reply author\",\"created\":\"D:20260810110000Z\","
        "\"modified\":\"D:20260810110000Z\",\"contents\":\"The question is whether there is an irrecoverable error or whether it still brings no useful information.\",\"flags\":4}\n"
        "{\"schema_version\":5,\"id\":\"reply-two\",\"in_reply_to\":\"reply-one\",\"revision\":1,"
        "\"updated_at\":\"2026-08-10T12:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":4,\"subtype\":\"Text\",\"rect\":[180,60,240,120],"
        "\"author\":\"Later author\",\"created\":\"D:20260810120000Z\","
        "\"modified\":\"D:20260810120000Z\",\"contents\":\"We selected a subset of problems and split each one into ten intervals with a high-resolution value function.\",\"flags\":4}\n";
    QFile originPdf(pdfPath);
    QVERIFY(originPdf.open(QIODevice::ReadOnly));
    const auto originHash = QCryptographicHash::hash(originPdf.readAll(), QCryptographicHash::Sha256).toHex();
    QByteArray hashField("\"schema_version\":5,\"annotation_pdf_sha256\":\"");
    hashField.append(originHash).append("\",");
    sidecar.replace("\"schema_version\":5,", hashField);
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 3000);
    QFile file(root.filePath(QStringLiteral("comments/open_comments.jsonl")));
    QVERIFY(file.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text));
    QCOMPARE(file.write(sidecar), sidecar.size());
    file.close();

    // The test supplies the canonical comments; keep repository snapshots from replacing them.
    QVERIFY(QObject::disconnect(part.m_fedoraRepository, SIGNAL(projectionsChanged(QJsonObject, qint64)), &part, nullptr));
    part.m_hasFedoraProjectionSnapshot = true;
    addLogicalComments(part.m_fedoraProjections, pdfPath, sidecar);
    part.refreshDocsCommentsFromSidecar();
    // Replies are placed with their thread root, not with their own legacy placement.
    QCOMPARE(part.m_document->page(2)->annotations().size(), 3);
    QCOMPARE(part.m_document->page(3)->annotations().size(), 0);
    Okular::Annotation *rootAnnotation = part.m_document->page(2)->annotation(QStringLiteral("root"));
    Okular::Annotation *firstReply = part.m_document->page(2)->annotation(QStringLiteral("reply-one"));
    Okular::Annotation *secondReply = part.m_document->page(2)->annotation(QStringLiteral("reply-two"));
    QVERIFY(rootAnnotation);
    QVERIFY(firstReply);
    QVERIFY(secondReply);
    QCOMPARE(rootAnnotation->previousAnnotation(), nullptr);
    QCOMPARE(firstReply->previousAnnotation(), rootAnnotation);
    QCOMPARE(secondReply->previousAnnotation(), firstReply);
    QVERIFY(!(rootAnnotation->flags() & Okular::Annotation::Hidden));
    QVERIFY(firstReply->flags() & Okular::Annotation::Hidden);
    QVERIFY(secondReply->flags() & Okular::Annotation::Hidden);

    QVERIFY(part.openReviewAnnotation(QStringLiteral("reply-two"), 3));
    QTRY_COMPARE(part.m_document->viewport().pageNumber, 2);
    QTRY_COMPARE(part.m_pageView->findChildren<QFrame *>(QStringLiteral("AnnotWindow")).size(), 1);
    QFrame *window = part.m_pageView->findChild<QFrame *>(QStringLiteral("AnnotWindow"));
    const QList<QLabel *> authors = window->findChildren<QLabel *>(QStringLiteral("annotationThreadAuthor"));
    const QList<QLabel *> contents = window->findChildren<QLabel *>(QStringLiteral("annotationThreadContent"));
    QCOMPARE(authors.size(), 2);
    QCOMPARE(contents.size(), 2);
    QVERIFY(authors.at(0)->text().contains(QStringLiteral("Root author")));
    QVERIFY(authors.at(1)->text().contains(QStringLiteral("Reply author")));
    QCOMPARE(contents.at(0)->text(), QStringLiteral("This allows us to determine what an irrecoverable error really looks like."));
    QCOMPARE(contents.at(1)->text(), QStringLiteral("The question is whether there is an irrecoverable error or whether it still brings no useful information."));
    const QString rootCreation = QLocale().toString(QDateTime(QDate(2026, 8, 10), QTime(8, 0), QTimeZone::UTC).toLocalTime(), QLocale::ShortFormat);
    const QString rootModification = QLocale().toString(QDateTime(QDate(2026, 8, 10), QTime(10, 0), QTimeZone::UTC).toLocalTime(), QLocale::ShortFormat);
    const auto dates = window->findChildren<QLabel *>(QStringLiteral("annotationMessageDate"));
    QCOMPARE(dates.size(), 3);
    QCOMPARE(dates.at(0)->text(), rootCreation);
    QVERIFY(dates.at(0)->text() != rootModification);
    QTextEdit *editor = window->findChild<QTextEdit *>();
    QCOMPARE(editor->toPlainText(), QStringLiteral("We selected a subset of problems and split each one into ten intervals with a high-resolution value function."));

    window->resize(460, 520);
    QCoreApplication::processEvents();
    QScrollArea *threadScrollArea = window->findChild<QScrollArea *>(QStringLiteral("annotationThreadScrollArea"));
    QLabel *currentAuthor = window->findChild<QLabel *>(QStringLiteral("annotationAuthorAndDateLabel"));
    QLabel *threadCount = window->findChild<QLabel *>(QStringLiteral("annotationThreadCount"));
    QPushButton *replyButton = window->findChild<QPushButton *>(QStringLiteral("annotationReply"));
    QVERIFY(threadScrollArea);
    QVERIFY(currentAuthor);
    QVERIFY(threadCount);
    QVERIFY(replyButton);
    QVERIFY(threadScrollArea->isVisible());
    QVERIFY(threadScrollArea->height() > 112);
    QCOMPARE(threadScrollArea->horizontalScrollBarPolicy(), Qt::ScrollBarAlwaysOff);
    QCOMPARE(threadScrollArea->horizontalScrollBar()->maximum(), 0);
    QCOMPARE(editor->horizontalScrollBar()->value(), 0);
    QCOMPARE(editor->verticalScrollBarPolicy(), Qt::ScrollBarAlwaysOff);
    QCOMPARE(threadCount->text(), QStringLiteral("3 messages"));
    QVERIFY(window->palette().color(QPalette::Window) != QColor(Qt::yellow));
    QVERIFY(window->width() >= 340);

    const auto topInWindow = [window](const QWidget *widget) { return widget->mapTo(window, QPoint(0, 0)).y(); };
    const auto bottomInWindow = [window](const QWidget *widget) { return widget->mapTo(window, QPoint(0, widget->height())).y(); };
    QVERIFY2(bottomInWindow(threadScrollArea) <= topInWindow(replyButton), "The thread overlaps the Reply button.");
    QCOMPARE(currentAuthor->parentWidget(), editor->parentWidget());
    QCOMPARE(editor->parentWidget()->objectName(), QStringLiteral("annotationSelectedMessage"));
    QVERIFY2(currentAuthor->geometry().bottom() < editor->geometry().top(), "The selected comment author overlaps its editor.");
    QVERIFY2(currentAuthor->y() <= 20, "The author must stay at the top of its message when the popup is tall.");
    QVERIFY2(editor->y() - currentAuthor->geometry().bottom() < 55, "The selected message must stay next to its author and timestamp.");
    for (int index = 0; index < authors.size(); ++index) {
        QCOMPARE(authors.at(index)->parentWidget(), contents.at(index)->parentWidget());
        QVERIFY2(authors.at(index)->geometry().bottom() < contents.at(index)->geometry().top(), "A thread author overlaps the corresponding comment body.");
        QVERIFY2(authors.at(index)->y() <= 20, "A reply author must not float in unused vertical space.");
        QVERIFY2(contents.at(index)->y() - authors.at(index)->geometry().bottom() < 55, "Reply text must stay next to its author and timestamp.");
    }
    QVERIFY2(topInWindow(authors.at(0)->parentWidget()) < topInWindow(authors.at(1)->parentWidget()), "The root comment must precede its first reply.");
    QVERIFY2(topInWindow(authors.at(1)->parentWidget()) < topInWindow(editor->parentWidget()), "The first reply must precede the selected later reply.");

    QTest::mouseClick(replyButton, Qt::LeftButton);
    QWidget *composerPanel = window->findChild<QWidget *>(QStringLiteral("annotationReplyComposerPanel"));
    QTextEdit *composer = window->findChild<QTextEdit *>(QStringLiteral("annotationReplyComposer"));
    QPushButton *sendReply = window->findChild<QPushButton *>(QStringLiteral("annotationReplySend"));
    QPushButton *cancelReply = window->findChild<QPushButton *>(QStringLiteral("annotationReplyCancel"));
    QVERIFY(composerPanel);
    QVERIFY(composer);
    QVERIFY(sendReply);
    QVERIFY(cancelReply);
    QVERIFY(composerPanel->isVisible());
    QVERIFY(!replyButton->isVisible());
    if (!qEnvironmentVariableIsEmpty("THOUGHTS_THREAD_QA_DIR")) {
        QTest::qWait(100);
        threadScrollArea->verticalScrollBar()->setValue(0);
        window->grab().save(QDir(qEnvironmentVariable("THOUGHTS_THREAD_QA_DIR")).filePath(QStringLiteral("three-messages.png")));
    }
    composer->setPlainText(QStringLiteral("Inline reply draft"));
    QPointer<QFrame> activeWindow(window);
    auto *backgroundComment = new Okular::TextAnnotation();
    backgroundComment->setUniqueName(QStringLiteral("background-comment"));
    backgroundComment->setContents(QStringLiteral("Updated on another page"));
    part.m_document->addPageAnnotationFromExternalSource(0, backgroundComment);
    QVERIFY2(activeWindow, "Background refresh dismissed the popup while composing a reply");
    QCOMPARE(composer->toPlainText(), QStringLiteral("Inline reply draft"));
    QVERIFY(sendReply->isEnabled());
    QTest::mouseClick(cancelReply, Qt::LeftButton);
    QVERIFY(!composerPanel->isVisible());
    QVERIFY(replyButton->isVisible());

    QTest::mouseClick(replyButton, Qt::LeftButton);
    QVERIFY(QObject::disconnect(window, SIGNAL(replyRequested(QString)), part.m_pageView, nullptr));
    QSignalSpy inlineReplyRequested(window, SIGNAL(replyRequested(QString)));
    composer->setPlainText(QStringLiteral("Inline reply saved"));
    QTest::mouseClick(sendReply, Qt::LeftButton);
    QCOMPARE(inlineReplyRequested.size(), 1);
    QCOMPARE(inlineReplyRequested.constFirst().constFirst().toString(), QStringLiteral("Inline reply saved"));
}

void PartTest::testDocsCommentThreadCompactLayout()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/thread.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));
    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(QMetaObject::invokeMethod(part.m_pageView, "setDocsRoot", Q_ARG(QString, docsRoot.path())));
    QVERIFY(openDocument(&part, pdfPath));
    part.widget()->resize(900, 800);
    part.widget()->show();
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 2000);
    QTRY_VERIFY_WITH_TIMEOUT(!part.m_docsCommentFingerprint.isEmpty(), 3000);

    auto *original = new Okular::TextAnnotation();
    original->setUniqueName(QStringLiteral("compact-thread-root"));
    original->setBoundingRectangle(Okular::NormalizedRect(0.2, 0.2, 0.25, 0.25));
    original->setAuthor(QStringLiteral("Alex Example"));
    original->setCreationDate(QDateTime(QDate(2026, 8, 6), QTime(21, 21)));
    original->setContents(QStringLiteral("How much data is it used for dpo, specifically for preference optimization"));
    original->style().setColor(Qt::yellow);
    part.m_document->addPageAnnotation(0, original);
    QVERIFY(part.openReviewAnnotation(QStringLiteral("compact-thread-root"), 1));
    QFrame *window = part.m_pageView->findChild<QFrame *>(QStringLiteral("AnnotWindow"));
    QVERIFY(window);
    auto *scroll = window->findChild<QScrollArea *>(QStringLiteral("annotationThreadScrollArea"));
    auto *editor = window->findChild<QTextEdit *>(QStringLiteral("annotationSelectedEditor"));
    auto *author = window->findChild<QLabel *>(QStringLiteral("annotationAuthorAndDateLabel"));
    QVERIFY(scroll);
    QVERIFY(editor);
    QVERIFY(author);
    QTRY_VERIFY(window->height() < 300);
    QTRY_COMPARE(scroll->verticalScrollBar()->maximum(), 0);
    QTRY_VERIFY(author->y() <= 20);
    QTRY_VERIFY(editor->y() - author->geometry().bottom() < 55);
    const auto capture = [window](const QString &name) {
        const QString directory = qEnvironmentVariable("THOUGHTS_THREAD_QA_DIR");
        if (!directory.isEmpty()) {
            QDir().mkpath(directory);
            window->grab().save(QDir(directory).filePath(name + QStringLiteral(".png")));
        }
    };
    QTest::qWait(100);
    capture(QStringLiteral("single"));
    window->resize(440, 600);
    QTRY_VERIFY(author->y() <= 20);
    QTRY_VERIFY(editor->y() - author->geometry().bottom() < 55);
    QTRY_VERIFY(editor->parentWidget()->height() < 180);

    auto *replyButton = window->findChild<QPushButton *>(QStringLiteral("annotationReply"));
    auto *related = window->findChild<QToolButton *>(QStringLiteral("annotationRelatedToggle"));
    QVERIFY(replyButton);
    QVERIFY(related);
    QCOMPARE(related->parentWidget(), replyButton->parentWidget());
    QTest::mouseClick(replyButton, Qt::LeftButton);
    auto *composer = window->findChild<QTextEdit *>(QStringLiteral("annotationReplyComposer"));
    auto *cancel = window->findChild<QPushButton *>(QStringLiteral("annotationReplyCancel"));
    QVERIFY(composer);
    QVERIFY(cancel);
    QTRY_VERIFY(composer->isVisible());
    QVERIFY(replyButton->parentWidget()->isVisible());
    QTest::mouseClick(cancel, Qt::LeftButton);
    QTRY_VERIFY(window->height() < 300);

    // Grow the same conversation past the popup limit and keep the composer outside its scroll area.
    for (int index = 0; index < 12; ++index) {
        auto *reply = new Okular::TextAnnotation();
        reply->setUniqueName(QStringLiteral("compact-reply-%1").arg(index));
        reply->setPreviousAnnotation(original);
        reply->setAuthor(index % 2 ? QStringLiteral("Alex Example") : QStringLiteral("Collaborator"));
        reply->setCreationDate(original->creationDate().addSecs((index + 1) * 60));
        reply->setContents(index % 2 ? QStringLiteral("The number of preference pairs, after filtering.")
                                    : QStringLiteral("Do you mean the number of preference pairs, or the total number of training tokens?"));
        reply->setBoundingRectangle(original->boundingRectangle());
        part.m_document->addPageAnnotation(0, reply);
    }
    QVERIFY(part.openReviewAnnotation(QStringLiteral("compact-thread-root"), 1));
    QTRY_VERIFY(scroll->verticalScrollBar()->maximum() > 0);
    QVERIFY(window->height() <= 560);
    QTest::mouseClick(replyButton, Qt::LeftButton);
    QTRY_VERIFY(composer->isVisible());
    QTRY_COMPARE(window->height(), 560);
    QCoreApplication::processEvents();
    const QPoint composerPosition = composer->mapTo(window, QPoint());
    const QPoint headerPosition = window->findChild<QLabel *>(QStringLiteral("annotationTitleLabel"))->mapTo(window, QPoint());
    scroll->verticalScrollBar()->setValue(scroll->verticalScrollBar()->maximum());
    QCoreApplication::processEvents();
    QCOMPARE(composer->mapTo(window, QPoint()), composerPosition);
    QCOMPARE(window->findChild<QLabel *>(QStringLiteral("annotationTitleLabel"))->mapTo(window, QPoint()), headerPosition);
    QCOMPARE(scroll->horizontalScrollBar()->maximum(), 0);
    QVERIFY(scroll->mapTo(window, QPoint(0, scroll->height())).y() <= composerPosition.y());
    capture(QStringLiteral("long-thread"));
    window->resize(340, window->height());
    QTRY_COMPARE(scroll->horizontalScrollBar()->maximum(), 0);
    capture(QStringLiteral("narrow-thread"));
}

void PartTest::testDocsCommentSidecarCrossPageRefresh()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file2.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(openDocument(&part, pdfPath));
    QCOMPARE(part.m_document->pages(), 2U);

    const QString sidecarPath = root.filePath(QStringLiteral("comments/open_comments.jsonl"));
    QFile sidecar(sidecarPath);
    QVERIFY(sidecar.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text));
    const QByteArray record =
        "{\"schema_version\":3,\"id\":\"cross-page\",\"revision\":1,"
        "\"updated_at\":\"2026-07-28T10:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":1,\"subtype\":\"Highlight\",\"rect\":[20,20,160,40],"
        "\"quad_points\":[20,40,160,40,20,20,160,20],"
        "\"fragments\":["
        "{\"page\":1,\"rect\":[20,20,160,40],\"quad_points\":[20,40,160,40,20,20,160,20]},"
        "{\"page\":2,\"rect\":[20,700,160,720],\"quad_points\":[20,720,160,720,20,700,160,700]}],"
        "\"author\":\"Phone author\",\"contents\":\"one logical comment\","
        "\"created\":\"D:20260728100000Z\",\"modified\":\"D:20260728100000Z\","
        "\"flags\":4,\"opacity\":1}\n";
    QCOMPARE(sidecar.write(record), record.size());
    sidecar.close();

    part.refreshDocsCommentsFromSidecar();

    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    QCOMPARE(part.m_document->page(1)->annotations().size(), 1);
    Okular::Annotation *const rootAnnotation = part.m_document->page(0)->annotations().constFirst();
    Okular::Annotation *const continuation = part.m_document->page(1)->annotations().constFirst();
    QCOMPARE(rootAnnotation->uniqueName(), QStringLiteral("cross-page"));
    QCOMPARE(continuation->uniqueName(), Thoughts::makeCommentFragmentId(QStringLiteral("cross-page"), 1));
    QCOMPARE(rootAnnotation->contents(), QStringLiteral("one logical comment"));
    QVERIFY(continuation->contents().isEmpty());

    QJsonObject snapshot;
    QString failure;
    QVERIFY2(part.writeDocsCommentSnapshot(QUrl::fromLocalFile(pdfPath), &snapshot, &failure), qPrintable(failure));
    const QJsonArray comments = snapshot.value(QStringLiteral("comments")).toArray();
    QCOMPARE(comments.size(), 1);
    QCOMPARE(comments.at(0).toObject().value(QStringLiteral("fragments")).toArray().size(), 2);

    continuation->setUniqueName(Thoughts::makeCommentFragmentId(QStringLiteral("cross-page"), 2));
    QJsonObject malformedSnapshot;
    QVERIFY2(part.writeDocsCommentSnapshot(QUrl::fromLocalFile(pdfPath), &malformedSnapshot, &failure), qPrintable(failure));
    const QJsonArray malformedComments = malformedSnapshot.value(QStringLiteral("comments")).toArray();
    QCOMPARE(malformedComments.size(), 2);
    QVERIFY(!malformedComments.at(0).toObject().contains(QStringLiteral("fragments")));
    QVERIFY(!malformedComments.at(1).toObject().contains(QStringLiteral("fragments")));
    continuation->setUniqueName(Thoughts::makeCommentFragmentId(QStringLiteral("cross-page"), 1));

    QFile deletion(sidecarPath);
    QVERIFY(deletion.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text));
    const QByteArray tombstone =
        "{\"schema_version\":3,\"id\":\"cross-page\",\"revision\":2,"
        "\"updated_at\":\"2026-07-28T10:01:00Z\",\"deleted_at\":\"2026-07-28T10:01:00Z\","
        "\"origin_id\":\"android-mj-pdf\",\"deleted\":true,\"page\":1,"
        "\"subtype\":\"Highlight\",\"rect\":[20,20,160,40],\"contents\":\"one logical comment\"}\n";
    const QByteArray legacyTextComment =
        "{\"schema_version\":5,\"id\":\"legacy-note-icon\",\"revision\":1,"
        "\"updated_at\":\"2026-07-28T10:01:00Z\",\"origin_id\":\"desktop\","
        "\"page\":1,\"subtype\":\"Text\",\"name\":\"Note\","
        "\"rect\":[60,60,84,84],\"color\":[1,1,0],\"contents\":\"legacy icon\"}\n";
    QCOMPARE(deletion.write(tombstone + legacyTextComment), tombstone.size() + legacyTextComment.size());
    deletion.close();
    part.refreshDocsCommentsFromSidecar();
    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    QCOMPARE(part.m_document->page(1)->annotations().size(), 0);
    QCOMPARE(part.m_document->page(0)->annotations().constFirst()->subType(), Okular::Annotation::AText);
    const auto *legacyAnnotation = static_cast<Okular::TextAnnotation *>(part.m_document->page(0)->annotations().constFirst());
    QCOMPARE(legacyAnnotation->textIcon(), QStringLiteral("Comment"));
}

void PartTest::testDocsManagedOpenIgnoresEmbeddedAnnotations()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file2.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));

    const QString deletedId = QStringLiteral("deleted-before-open");
    const QString unrelatedId = QStringLiteral("unmanaged-annotation");
    {
        Okular::Part writer(nullptr, {});
        QVERIFY(openDocument(&writer, pdfPath));
        QCOMPARE(writer.m_document->pages(), 2U);

        auto *rootAnnotation = new Okular::TextAnnotation();
        rootAnnotation->setTextType(Okular::TextAnnotation::Linked);
        rootAnnotation->setUniqueName(deletedId);
        rootAnnotation->setBoundingRectangle(Okular::NormalizedRect(0.1, 0.1, 0.2, 0.2));
        rootAnnotation->setContents(QStringLiteral("deleted on the phone"));
        writer.m_document->addPageAnnotation(0, rootAnnotation);

        auto *continuation = new Okular::HighlightAnnotation();
        continuation->setUniqueName(Thoughts::makeCommentFragmentId(deletedId, 1));
        continuation->setBoundingRectangle(Okular::NormalizedRect(0.1, 0.1, 0.3, 0.2));
        writer.m_document->addPageAnnotation(1, continuation);

        auto *unrelated = new Okular::TextAnnotation();
        unrelated->setTextType(Okular::TextAnnotation::Linked);
        unrelated->setUniqueName(unrelatedId);
        unrelated->setBoundingRectangle(Okular::NormalizedRect(0.4, 0.4, 0.5, 0.5));
        unrelated->setContents(QStringLiteral("not managed by the sidecar"));
        writer.m_document->addPageAnnotation(0, unrelated);

        QVERIFY(writer.saveAs(QUrl::fromLocalFile(pdfPath)));
    }
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));

    {
        Okular::Part externalReader(nullptr, {});
        QVERIFY(openDocument(&externalReader, pdfPath));
        QCOMPARE(externalReader.m_document->page(0)->annotations().size(), 2);
        QCOMPARE(externalReader.m_document->page(1)->annotations().size(), 1);
    }

    const auto writeTombstone = [&root, &deletedId] {
        const QJsonObject tombstone {
            {QStringLiteral("schema_version"), 4},
            {QStringLiteral("id"), deletedId},
            {QStringLiteral("revision"), 2},
            {QStringLiteral("updated_at"), QStringLiteral("2026-07-29T11:45:47Z")},
            {QStringLiteral("deleted_at"), QStringLiteral("2026-07-29T11:45:47Z")},
            {QStringLiteral("origin_id"), QStringLiteral("android-mj-pdf")},
            {QStringLiteral("deleted"), true},
            {QStringLiteral("page"), 1},
            {QStringLiteral("subtype"), QStringLiteral("Text")},
            {QStringLiteral("rect"), QJsonArray {60, 60, 120, 120}},
            {QStringLiteral("contents"), QStringLiteral("deleted on the phone")},
        };
        QFile sidecar(root.filePath(QStringLiteral("comments/open_comments.jsonl")));
        return sidecar.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text) && sidecar.write(QJsonDocument(tombstone).toJson(QJsonDocument::Compact) + '\n') > 0;
    };

    {
        Okular::Part part(nullptr, {});
        part.m_docsRenderRoot = docsRoot.path();
        QVERIFY(openDocument(&part, pdfPath));
        QCOMPARE(part.m_document->page(0)->annotations().size(), 0);
        QCOMPARE(part.m_document->page(1)->annotations().size(), 0);

        QVERIFY(writeTombstone());
        part.refreshDocsCommentsFromSidecar();
        QCOMPARE(part.m_document->page(0)->annotations().size(), 0);
        QCOMPARE(part.m_document->page(1)->annotations().size(), 0);
        QVERIFY(!part.isModified());
    }

    Okular::Part reopened(nullptr, {});
    reopened.m_docsRenderRoot = docsRoot.path();
    QVERIFY(openDocument(&reopened, pdfPath));
    QTRY_COMPARE_WITH_TIMEOUT(reopened.m_document->page(0)->annotations().size(), 0, 5000);
    QCOMPARE(reopened.m_document->page(1)->annotations().size(), 0);
    QVERIFY(!reopened.isModified());
}

void PartTest::testDocsCommentPhoneDeletionRemovesSourceAnchorInPlace()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments/.layout")));
    QVERIFY(root.mkpath(QStringLiteral("docs-one/src")));

    const auto writeFile = [](const QString &path, const QByteArray &contents) {
        QFile file(path);
        return file.open(QIODevice::WriteOnly | QIODevice::Truncate) && file.write(contents) == contents.size();
    };
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    const QString sourcePath = root.filePath(QStringLiteral("docs-one/src/section.tex"));
    const QString sidecarPath = root.filePath(QStringLiteral("comments/open_comments.jsonl"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));
    QVERIFY(writeFile(sourcePath, "\\CommentAnchor{phone-anchor}{delete me}{Anchor target sentence.}\n"));

    const QJsonObject layout {
        {QStringLiteral("version"), 1},
        {QStringLiteral("sources"),
         QJsonArray {
             QJsonObject {
                 {QStringLiteral("fingerprint"), QStringLiteral("source-fingerprint")},
                 {QStringLiteral("page_count"), 1},
                 {QStringLiteral("source_id"), QStringLiteral("docs-one/src/section.tex")},
                 {QStringLiteral("start_page"), 1},
             },
         }},
    };
    QVERIFY(writeFile(root.filePath(QStringLiteral("comments/.layout/open.json")), QJsonDocument(layout).toJson(QJsonDocument::Compact)));
    const QByteArray liveComment =
        "{\"schema_version\":2,\"id\":\"phone-note\",\"review_key\":\"id:phone-note\","
        "\"revision\":1,\"updated_at\":\"2026-07-28T10:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":1,\"subtype\":\"Text\",\"rect\":[60,60,120,120],"
        "\"author\":\"Phone author\",\"contents\":\"delete me\","
        "\"created\":\"D:20260728120000+02'00'\",\"modified\":\"D:20260728120000+02'00'\","
        "\"flags\":4,\"opacity\":1,\"anchor_id\":\"phone-anchor\","
        "\"anchor_status\":\"anchored\",\"anchor_confidence\":\"high\","
        "\"tex_file\":\"docs-one/src/section.tex\",\"tex_line\":1}\n";
    QVERIFY(writeFile(sidecarPath, liveComment));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    // The test supplies the canonical comments; keep repository snapshots from replacing them.
    QVERIFY(QObject::disconnect(part.m_fedoraRepository, SIGNAL(projectionsChanged(QJsonObject, qint64)), &part, nullptr));
    part.m_hasFedoraProjectionSnapshot = true;
    addLogicalComments(part.m_fedoraProjections, pdfPath, liveComment);
    QVERIFY(openDocument(&part, pdfPath));
    QTRY_COMPARE_WITH_TIMEOUT(part.m_document->page(0)->annotations().size(), 1, 5000);
    QTRY_VERIFY_WITH_TIMEOUT(!part.m_docsSourceReconcileTimer->isActive() && !part.m_docsSourceReconcileRunning, 5000);
    const QUrl originalUrl = part.m_document->currentDocument();
    QSignalSpy mimeTypeChangedSpy(&part, &Okular::Part::mimeTypeChanged);

    QJsonObject tombstone = QJsonDocument::fromJson(liveComment).object();
    tombstone.insert(QStringLiteral("revision"), 2);
    tombstone.insert(QStringLiteral("updated_at"), QStringLiteral("2026-07-28T10:01:00Z"));
    tombstone.insert(QStringLiteral("deleted_at"), QStringLiteral("2026-07-28T10:01:00Z"));
    tombstone.insert(QStringLiteral("deleted"), true);
    QVERIFY(writeFile(sidecarPath, QJsonDocument(tombstone).toJson(QJsonDocument::Compact) + '\n'));
    addLogicalComments(part.m_fedoraProjections, pdfPath, QJsonDocument(tombstone).toJson(QJsonDocument::Compact));
    part.refreshDocsCommentsFromSidecar();

    QTRY_COMPARE_WITH_TIMEOUT(part.m_document->page(0)->annotations().size(), 0, 5000);
    QTRY_VERIFY_WITH_TIMEOUT(
        [&sourcePath] {
            QFile source(sourcePath);
            if (!source.open(QIODevice::ReadOnly)) {
                return false;
            }
            const QByteArray contents = source.readAll();
            return !contents.contains("\\CommentAnchor{phone-anchor}") && contents.contains("Anchor target sentence.");
        }(),
        5000);
    QTRY_VERIFY_WITH_TIMEOUT(!part.m_docsSourceReconcileTimer->isActive() && !part.m_docsSourceReconcileRunning, 5000);
    QCOMPARE(part.m_document->currentDocument(), originalUrl);
    QCOMPARE(mimeTypeChangedSpy.count(), 0);
    QVERIFY(!part.isModified());

    QFile storedSidecar(sidecarPath);
    QVERIFY(storedSidecar.open(QIODevice::ReadOnly));
    const QByteArray storedTombstone = storedSidecar.readAll();
    QVERIFY(storedTombstone.contains("\"deleted\":true"));
    QVERIFY(storedTombstone.contains("\"origin_id\":\"android-mj-pdf\""));
    QFile resolution(root.filePath(QStringLiteral("comments/review_resolutions.jsonl")));
    if (resolution.exists()) {
        QVERIFY(resolution.open(QIODevice::ReadOnly));
        QVERIFY(!resolution.readAll().contains("\"id\":\"phone-note\""));
    }
    QFile sourceLog(part.m_docsSourceSyncLogPath);
    QVERIFY(sourceLog.open(QIODevice::ReadOnly));
    const QByteArray sourceLogData = sourceLog.readAll();
    QVERIFY2(sourceLogData.contains("removed=1"), sourceLogData.constData());
    QVERIFY2(sourceLogData.contains("removal-skips=0"), sourceLogData.constData());

    DocsCommentSynchronizer synchronizer({
        .docsRoot = docsRoot.path(),
        .processEnvironment = QProcessEnvironment::systemEnvironment(),
    });
    const DocsCommentSynchronizer::Result repeated = synchronizer.reconcileSourceAnchorChanges(QUrl::fromLocalFile(pdfPath));
    QVERIFY2(repeated.success, qPrintable(repeated.failureReason));
    QCOMPARE(repeated.anchorsRemoved, 0);
}

void PartTest::testDocsHeadlessDeletionUsesExactPdfObject()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments/.layout")));
    QVERIFY(root.mkpath(QStringLiteral("docs-one/src")));

    const auto writeFile = [](const QString &path, const QByteArray &contents) {
        QFile file(path);
        return file.open(QIODevice::WriteOnly | QIODevice::Truncate) && file.write(contents) == contents.size();
    };
    const QString currentPdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    const QString exactPdfPath = root.filePath(QStringLiteral("object-without-extension"));
    const QString sourcePath = root.filePath(QStringLiteral("docs-one/src/section.tex"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file2.pdf"), currentPdfPath));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), exactPdfPath));
    QVERIFY(writeFile(sourcePath, "\\CommentAnchor{deleted-note}{delete me}{Anchor target sentence.}\n"));
    QVERIFY(writeFile(root.filePath(QStringLiteral("comments/.layout/open.json")),
                      "{\"version\":1,\"page_count\":1,\"sources\":[{\"fingerprint\":\"source-fingerprint\","
                      "\"page_count\":1,\"source_id\":\"docs-one/src/section.tex\",\"start_page\":1}]}"));

    const QJsonObject tombstone {
        {QStringLiteral("schema_version"), 5},
        {QStringLiteral("id"), QStringLiteral("deleted-note")},
        {QStringLiteral("annotation_id"), QStringLiteral("deleted-note")},
        {QStringLiteral("review_key"), QStringLiteral("id:deleted-note")},
        {QStringLiteral("revision"), 2},
        {QStringLiteral("updated_at"), QStringLiteral("2026-08-27T12:00:00Z")},
        {QStringLiteral("origin_id"), QStringLiteral("thoughts-logical-comments")},
        {QStringLiteral("deleted"), true},
        {QStringLiteral("discussion"), true},
        {QStringLiteral("page"), 1},
        {QStringLiteral("subtype"), QStringLiteral("Text")},
        {QStringLiteral("rect"), QJsonArray {60, 60, 120, 120}},
        {QStringLiteral("contents"), QStringLiteral("delete me")},
        // A tombstone's historical PDF identity may no longer match the
        // current rebuilt PDF. Source-anchor deletion does not need geometry.
        {QStringLiteral("annotation_pdf_sha256"), QString(64, QLatin1Char('a'))},
        {QStringLiteral("anchor_id"), QStringLiteral("deleted-note")},
        {QStringLiteral("anchor_status"), QStringLiteral("anchored")},
        {QStringLiteral("tex_file"), QStringLiteral("docs-one/src/section.tex")},
        {QStringLiteral("tex_line"), 1},
    };
    QVERIFY(writeFile(root.filePath(QStringLiteral("comments/open_comments.jsonl")), QJsonDocument(tombstone).toJson(QJsonDocument::Compact) + '\n'));

    DocsCommentSynchronizer synchronizer({
        .docsRoot = docsRoot.path(),
        .processEnvironment = QProcessEnvironment::systemEnvironment(),
    });
    const DocsCommentSynchronizer::Result result = synchronizer.prepareAnnotation(
        QStringLiteral("open"),
        QStringLiteral("deleted-note"),
        [](const QString &, int, QString *) -> std::optional<DocsCommentSynchronizer::PageGeometry> { return DocsCommentSynchronizer::PageGeometry {.width = 612.0, .height = 792.0, .rotation = 0}; },
        exactPdfPath);
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorsRemoved, 1);
    QFile source(sourcePath);
    QVERIFY(source.open(QIODevice::ReadOnly));
    QVERIFY(!source.readAll().contains("\\CommentAnchor{deleted-note}"));
}

void PartTest::testDocsPlainMarkupRemovesLegacyAnchorButRemainsVisible()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments/.layout")));
    QVERIFY(root.mkpath(QStringLiteral("docs-one/src")));

    const auto writeFile = [](const QString &path, const QByteArray &contents) {
        QFile file(path);
        return file.open(QIODevice::WriteOnly | QIODevice::Truncate) && file.write(contents) == contents.size();
    };
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    const QString sourcePath = root.filePath(QStringLiteral("docs-one/src/section.tex"));
    const QString sidecarPath = root.filePath(QStringLiteral("comments/open_comments.jsonl"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));
    QVERIFY(writeFile(sourcePath, "\\CommentAnchor{plain-markup-anchor}{old comment}{Highlighted source text.}\n"));

    const QJsonObject layout {
        {QStringLiteral("version"), 1},
        {QStringLiteral("sources"),
         QJsonArray {
             QJsonObject {
                 {QStringLiteral("fingerprint"), QStringLiteral("source-fingerprint")},
                 {QStringLiteral("page_count"), 1},
                 {QStringLiteral("source_id"), QStringLiteral("docs-one/src/section.tex")},
                 {QStringLiteral("start_page"), 1},
             },
         }},
    };
    QVERIFY(writeFile(root.filePath(QStringLiteral("comments/.layout/open.json")), QJsonDocument(layout).toJson(QJsonDocument::Compact)));
    const QByteArray plainMarkup =
        "{\"schema_version\":4,\"id\":\"plain-markup\",\"review_key\":\"id:plain-markup\","
        "\"revision\":1,\"updated_at\":\"2026-08-08T10:00:00Z\",\"origin_id\":\"android-mj-pdf\","
        "\"page\":1,\"subtype\":\"Highlight\",\"rect\":[60,60,120,90],"
        "\"quad_points\":[60,90,120,90,60,60,120,60],"
        "\"author\":\"Phone author\",\"contents\":\"  \\n \\t\",\"selected_text\":\"Highlighted source text.\","
        "\"flags\":4,\"opacity\":1,\"anchor_id\":\"plain-markup-anchor\","
        "\"anchor_status\":\"anchored\",\"anchor_confidence\":\"high\","
        "\"tex_file\":\"docs-one/src/section.tex\",\"tex_line\":1}\n";
    QVERIFY(writeFile(sidecarPath, plainMarkup));

    DocsCommentSynchronizer synchronizer({
        .docsRoot = docsRoot.path(),
        .processEnvironment = QProcessEnvironment::systemEnvironment(),
    });
    const DocsCommentSynchronizer::Result result = synchronizer.reconcileSourceAnchorChanges(QUrl::fromLocalFile(pdfPath));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.visibleComments, 0);
    QCOMPARE(result.plainMarkups, 1);
    QCOMPARE(result.anchorsRemoved, 1);

    QFile source(sourcePath);
    QVERIFY(source.open(QIODevice::ReadOnly));
    QCOMPARE(source.readAll(), QByteArray("Highlighted source text.\n"));

    QFile sidecar(sidecarPath);
    QVERIFY(sidecar.open(QIODevice::ReadOnly));
    const QJsonObject stored = QJsonDocument::fromJson(sidecar.readLine()).object();
    QCOMPARE(stored.value(QStringLiteral("id")).toString(), QStringLiteral("plain-markup"));
    QCOMPARE(stored.value(QStringLiteral("contents")).toString(), QStringLiteral("  \n \t"));
    QVERIFY(!stored.contains(QStringLiteral("anchor_id")));
    QVERIFY(!stored.value(QStringLiteral("deleted")).toBool());
    QVERIFY(!DocsCommentSynchronizer::isTrackedCommentRecord(stored));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    // The test supplies the canonical comments; keep repository snapshots from replacing them.
    QVERIFY(QObject::disconnect(part.m_fedoraRepository, SIGNAL(projectionsChanged(QJsonObject, qint64)), &part, nullptr));
    part.m_hasFedoraProjectionSnapshot = true;
    addLogicalComments(part.m_fedoraProjections, pdfPath, plainMarkup);
    QVERIFY(openDocument(&part, pdfPath));
    QTRY_COMPARE_WITH_TIMEOUT(part.m_document->page(0)->annotations().size(), 1, 5000);
    QCOMPARE(part.m_document->page(0)->annotations().constFirst()->subType(), Okular::Annotation::AHighlight);

    Okular::Annotation *const renderedMarkup = part.m_document->page(0)->annotations().constFirst();
    const QString reviewText = QStringLiteral("Now this is a comment");
    // Edits reach the sidecar through the comment journal; the Library PDF is immutable.
    const auto storedMarkup = [&docsRoot] {
        QString error;
        const QList<QJsonObject> visible = DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("open"), nullptr, &error);
        return error.isEmpty() && visible.size() == 1 ? visible.constFirst() : QJsonObject();
    };
    part.m_document->editPageAnnotationContents(0, renderedMarkup, reviewText, reviewText.size(), renderedMarkup->contents().size(), renderedMarkup->contents().size());
    QTRY_COMPARE_WITH_TIMEOUT(storedMarkup().value(QStringLiteral("contents")).toString(), reviewText, 5000);
    QVERIFY(DocsCommentSynchronizer::isTrackedCommentRecord(storedMarkup()));

    const QString whitespace = QStringLiteral(" \n\t ");
    part.m_document->editPageAnnotationContents(0, renderedMarkup, whitespace, whitespace.size(), reviewText.size(), reviewText.size());
    QTRY_COMPARE_WITH_TIMEOUT(storedMarkup().value(QStringLiteral("contents")).toString(), whitespace, 5000);
    QVERIFY(!DocsCommentSynchronizer::isTrackedCommentRecord(storedMarkup()));
    QTRY_COMPARE_WITH_TIMEOUT(part.m_document->page(0)->annotations().size(), 1, 5000);
}

