void PartTest::testDocsCommentSyncKeepsUiResponsive()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(openDocument(&part, pdfPath));

    auto *annotation = new Okular::TextAnnotation();
    annotation->setTextType(Okular::TextAnnotation::Linked);
    annotation->setBoundingRectangle(Okular::NormalizedRect(0.1, 0.1, 0.2, 0.2));
    annotation->setContents(QStringLiteral("responsive synchronization"));
    part.m_document->addPageAnnotation(0, annotation);

    // Library PDFs are immutable, so explicit synchronization replaces the
    // former save-time synchronization into the managed PDF.
    QElapsedTimer timer;
    timer.start();
    QVERIFY(part.synchronizeDocsCommentsNow().value(QStringLiteral("success")).toBool());
    QVERIFY2(timer.elapsed() < 250, qPrintable(QStringLiteral("native synchronization took %1 ms").arg(timer.elapsed())));
    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    Okular::Annotation *const savedAnnotation = part.m_document->page(0)->annotations().constFirst();
    part.m_document->prepareToModifyAnnotationProperties(savedAnnotation);
    savedAnnotation->setContents(QStringLiteral("text-only edit"));
    part.m_document->modifyPageAnnotationProperties(0, savedAnnotation);
    timer.restart();
    QVERIFY(part.synchronizeDocsCommentsNow().value(QStringLiteral("success")).toBool());
    QVERIFY2(timer.elapsed() < 250, qPrintable(QStringLiteral("repeat native synchronization took %1 ms").arg(timer.elapsed())));
    QCOMPARE(part.m_document->page(0)->annotations().constFirst(), savedAnnotation);
    QVERIFY(!part.m_syncingDocsComments);
    QFile log(part.m_docsCommentSyncLogPath);
    QVERIFY(log.open(QIODevice::ReadOnly));
    const QByteArray output = log.readAll();
    QVERIFY2(output.contains("anchor-attempts=0"), output.constData());
    QVERIFY2(output.contains("unchanged=1"), output.constData());
}

void PartTest::testDocsCommentSyncAnchorsOnlyDelta()
{
#ifdef Q_OS_WIN
    QSKIP("This test runs POSIX shell scripts as helpers.");
#endif
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments/.layout")));
    QVERIFY(root.mkpath(QStringLiteral("docs-one/tex/source")));
    QVERIFY(root.mkpath(QStringLiteral("docs-one/src")));
    QVERIFY(root.mkpath(QStringLiteral(".runtime/comment_anchors/builds/build-id")));
    QVERIFY(root.mkpath(QStringLiteral(".runtime/comment_anchors/builds/build-id/sources")));
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(registerLibraryPdf(root.path(), pdfPath));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/document.pdf"))));

    const auto writeFile = [](const QString &path, const QByteArray &contents) {
        QFile file(path);
        if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            return false;
        }
        return file.write(contents) == contents.size();
    };
    const QString wrapperPath = root.filePath(QStringLiteral("docs-one/tex/source/main.tex"));
    const QString sourcePath = root.filePath(QStringLiteral("docs-one/src/section.tex"));
    const QByteArray wrapperText = "\\documentclass{article}\n\\begin{document}\n\\input{../../src/section.tex}\n\\end{document}\n";
    QVERIFY(writeFile(wrapperPath, wrapperText));
    QVERIFY(writeFile(sourcePath, "Preamble text.\nAnchor target sentence.\n"));
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/sources/0000.tex")), wrapperText));
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/sources/0001.tex")), "Preamble text.\nAnchor target sentence.\n"));
    // Anchors are only searched in recorded build sources, including this later move target.
    const QString movedSourcePath = root.filePath(QStringLiteral("docs-one/src/moved.tex"));
    QVERIFY(writeFile(movedSourcePath, "Moved target sentence.\n"));
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/sources/0002.tex")), "Moved target sentence.\n"));
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/document.synctex.gz")), "test"));
    QVERIFY(writeFile(root.filePath(QStringLiteral("comments/.layout/open.json")),
                      "{\"version\":1,\"page_count\":1,\"pdf_stem\":\"open_combined\",\"sources\":["
                      "{\"fingerprint\":\"pdf-fingerprint\",\"page_count\":1,\"source_id\":\"docs-one/tex/source/main.tex\","
                      "\"source_pdf\":\"docs-one/pdf/open.pdf\",\"start_page\":1}]}"));
    const QJsonObject mapping {
        {QStringLiteral("version"), 2},
        {QStringLiteral("build_id"), QStringLiteral("build-id")},
        {QStringLiteral("pdf_name"), QStringLiteral("document.pdf")},
        {QStringLiteral("source_fingerprint"), QStringLiteral("pdf-fingerprint")},
        {QStringLiteral("source_id"), QStringLiteral("docs-one/tex/source/main.tex")},
        {QStringLiteral("source_tex"), QStringLiteral("docs-one/tex/source/main.tex")},
        {QStringLiteral("source_tex_absolute"), wrapperPath},
        {QStringLiteral("synctex_fingerprint"), QStringLiteral("synctex-fingerprint")},
        {QStringLiteral("synctex_name"), QStringLiteral("document.synctex.gz")},
        {QStringLiteral("source_snapshots"),
         QJsonArray {
             QJsonObject {
                 {QStringLiteral("source_id"), QStringLiteral("docs-one/tex/source/main.tex")},
                 {QStringLiteral("source_tex_absolute"), wrapperPath},
                 {QStringLiteral("snapshot"), QStringLiteral("sources/0000.tex")},
                 {QStringLiteral("input_order"), 0},
                 {QStringLiteral("marker_eligible"), true},
             },
             QJsonObject {
                 {QStringLiteral("source_id"), QStringLiteral("docs-one/src/section.tex")},
                 {QStringLiteral("source_tex_absolute"), sourcePath},
                 {QStringLiteral("snapshot"), QStringLiteral("sources/0001.tex")},
                 {QStringLiteral("input_order"), 1},
                 {QStringLiteral("marker_eligible"), true},
             },
             QJsonObject {
                 {QStringLiteral("source_id"), QStringLiteral("docs-one/src/moved.tex")},
                 {QStringLiteral("source_tex_absolute"), movedSourcePath},
                 {QStringLiteral("snapshot"), QStringLiteral("sources/0002.tex")},
                 {QStringLiteral("input_order"), 2},
                 {QStringLiteral("marker_eligible"), true},
             },
         }},
    };
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/mapping.json")), QJsonDocument(mapping).toJson(QJsonDocument::Compact)));

    const QString synctexPath = root.filePath(QStringLiteral("fake-synctex.sh"));
    const QByteArray synctexScript = QByteArray("#!/bin/bash\n") + "count_file=\"" + root.filePath(QStringLiteral("synctex-count")).toUtf8() + "\"\n" +
        "count=0\n"
        "if test -f \"$count_file\"; then count=$(cat \"$count_file\"); fi\n"
        "echo $((count + 1)) > \"$count_file\"\n"
        "cat <<'EOF'\n"
        "SyncTeX result begin\n"
        "Input:" +
        sourcePath.toUtf8() + "\nLine:2\nColumn:1\nSyncTeX result end\nEOF\n";
    QVERIFY(writeFile(synctexPath, synctexScript));
    QVERIFY(QFile::setPermissions(synctexPath, QFileDevice::ReadOwner | QFileDevice::WriteOwner | QFileDevice::ExeOwner));

    QFile exactPdf(pdfPath);
    QVERIFY(exactPdf.open(QIODevice::ReadOnly));
    const QString exactPdfSha256 = QString::fromLatin1(QCryptographicHash::hash(exactPdf.readAll(), QCryptographicHash::Sha256).toHex());
    exactPdf.close();

    const auto makeComment = [&exactPdfSha256](const QString &id, const QJsonArray &rect, const QString &contents, const QString &modified) {
        return QJsonObject {
            {QStringLiteral("page"), 1},
            {QStringLiteral("page_width"), 612.0},
            {QStringLiteral("page_height"), 792.0},
            {QStringLiteral("page_rotation"), 0},
            {QStringLiteral("subtype"), QStringLiteral("Text")},
            {QStringLiteral("id"), id},
            {QStringLiteral("rect"), rect},
            {QStringLiteral("contents"), contents},
            {QStringLiteral("annotation_pdf_sha256"), exactPdfSha256},
            {QStringLiteral("created"), QStringLiteral("D:20260728120000+02'00'")},
            {QStringLiteral("modified"), modified},
        };
    };
    const auto makeSnapshot = [&pdfPath](const QJsonArray &comments) {
        return QJsonObject {
            {QStringLiteral("version"), 2},
            {QStringLiteral("coordinate_space"), QStringLiteral("normalized-default-page")},
            {QStringLiteral("source_pdf"), pdfPath},
            {QStringLiteral("comments"), comments},
        };
    };
    DocsCommentSynchronizer synchronizer({
        .docsRoot = docsRoot.path(),
        .synctexExecutable = synctexPath,
        .processEnvironment = QProcessEnvironment::systemEnvironment(),
    });

    QJsonObject primaryComment = makeComment(QStringLiteral("delta-primary"), QJsonArray {0.1, 0.1, 0.2, 0.2}, QStringLiteral("new comment"), QStringLiteral("D:20260728120000+02'00'"));
    DocsCommentSynchronizer::Result result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 1);
    QCOMPARE(result.anchorsInserted, 1);

    QFile countFile(root.filePath(QStringLiteral("synctex-count")));
    QVERIFY(countFile.open(QIODevice::ReadOnly));
    QCOMPARE(countFile.readAll().trimmed(), QByteArray("1"));
    countFile.close();
    QFile source(sourcePath);
    QVERIFY(source.open(QIODevice::ReadOnly));
    const QByteArray initiallyAnchoredSource = source.readAll();
    QCOMPARE(initiallyAnchoredSource.count("\\CommentAnchor{"), 1);
    QVERIFY(initiallyAnchoredSource.contains("}{new comment}%"));
    source.close();
    QFile wrapper(wrapperPath);
    QVERIFY(wrapper.open(QIODevice::ReadOnly));
    const QByteArray wrapperContents = wrapper.readAll();
    QVERIFY(wrapperContents.contains("\\DeclareRobustCommand{\\CommentAnchor}[2]"));
    QVERIFY(wrapperContents.contains("\\pdfstringdefDisableCommands"));
    wrapper.close();

    // Deleting one anchored annotation must remove its marker without
    // re-running SyncTeX for the unchanged annotation that remains.
    const QJsonObject deletionOnlyComment = makeComment(QStringLiteral("delta-delete"),
                                                        QJsonArray {0.4, 0.4, 0.5, 0.5},
                                                        QStringLiteral("delete without reanchoring"),
                                                        QStringLiteral("D:20260728120100+02'00'"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment, deletionOnlyComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 1);
    QCOMPARE(result.anchorsInserted, 1);
    QVERIFY(countFile.open(QIODevice::ReadOnly));
    QCOMPARE(countFile.readAll().trimmed(), QByteArray("2"));
    countFile.close();
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 0);
    QCOMPARE(result.anchorsRemoved, 1);
    QVERIFY(countFile.open(QIODevice::ReadOnly));
    QCOMPARE(countFile.readAll().trimmed(), QByteArray("2"));
    countFile.close();
    QVERIFY(source.open(QIODevice::ReadOnly));
    QCOMPARE(source.readAll().count("\\CommentAnchor{"), 1);
    source.close();

    primaryComment.insert(QStringLiteral("contents"), QStringLiteral("text changed only\nwith 50% & #1_{x} $5 ^ ~ \\ café"));
    primaryComment.insert(QStringLiteral("modified"), QStringLiteral("D:20260728120200+02'00'"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 0);
    QCOMPARE(result.anchorMirrorsUpdated, 1);
    QVERIFY(countFile.open(QIODevice::ReadOnly));
    QCOMPARE(countFile.readAll().trimmed(), QByteArray("2"));
    countFile.close();
    QVERIFY(source.open(QIODevice::ReadOnly));
    const QString mirroredSource = QString::fromUtf8(source.readAll());
    QVERIFY2(mirroredSource.contains(QStringLiteral("}{text changed only with 50\\% \\& \\#1\\_\\{x\\} \\$5 \\textasciicircum{} \\textasciitilde{} \\textbackslash{} café}%")), qPrintable(mirroredSource));
    source.close();

    primaryComment.insert(QStringLiteral("rect"), QJsonArray {0.2, 0.2, 0.3, 0.3});
    primaryComment.insert(QStringLiteral("modified"), QStringLiteral("D:20260728120300+02'00'"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 1);
    QVERIFY(countFile.open(QIODevice::ReadOnly));
    QCOMPARE(countFile.readAll().trimmed(), QByteArray("3"));
    countFile.close();
    QVERIFY(source.open(QIODevice::ReadOnly));
    QCOMPARE(source.readAll().count("\\CommentAnchor{"), 1);
    source.close();

    // Moving the marker to another recorded source is not a deletion.
    QVERIFY(source.open(QIODevice::ReadOnly));
    const QList<QByteArray> anchoredLines = source.readAll().split('\n');
    source.close();
    QByteArray markerLine;
    QByteArray sourceWithoutMarker;
    for (const QByteArray &line : anchoredLines) {
        if (line.trimmed().startsWith("\\CommentAnchor{")) {
            markerLine = line.trimmed();
        } else if (!line.isEmpty()) {
            sourceWithoutMarker += line + '\n';
        }
    }
    QVERIFY(!markerLine.isEmpty());
    QVERIFY(writeFile(sourcePath, sourceWithoutMarker));
    QVERIFY(writeFile(movedSourcePath, markerLine + "\nMoved target sentence.\n"));
    primaryComment.insert(QStringLiteral("contents"), QStringLiteral("marker moved"));
    primaryComment.insert(QStringLiteral("modified"), QStringLiteral("D:20260728120400+02'00'"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 0);
    QVERIFY(countFile.open(QIODevice::ReadOnly));
    QCOMPARE(countFile.readAll().trimmed(), QByteArray("3"));
    countFile.close();
    QFile comments(root.filePath(QStringLiteral("comments/open_comments.jsonl")));
    QVERIFY(comments.open(QIODevice::ReadOnly));
    const QByteArray movedRecord = comments.readAll();
    QVERIFY(movedRecord.contains("\"anchor_status\":\"anchored\""));
    QVERIFY2(movedRecord.contains("\"tex_file\":\"docs-one/src/moved.tex\""), movedRecord.constData());
    comments.close();

    // Removing a durable marker keeps the comment as anchor removed: the
    // placement is orphaned with its last known anchor, without a speculative lookup.
    QVERIFY(writeFile(movedSourcePath, "Moved target sentence.\n"));
    primaryComment.insert(QStringLiteral("contents"), QStringLiteral("marker disappeared"));
    primaryComment.insert(QStringLiteral("modified"), QStringLiteral("D:20260728120500+02'00'"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 0);
    QCOMPARE(result.sourceAnchorsOrphaned, 1);
    QCOMPARE(result.sourceAnchorDeletions, 0);
    QVERIFY(countFile.open(QIODevice::ReadOnly));
    QCOMPARE(countFile.readAll().trimmed(), QByteArray("3"));
    countFile.close();
    const auto primaryRecord = [&comments] {
        QJsonObject found;
        if (!comments.open(QIODevice::ReadOnly)) return found;
        for (const QByteArray &line : comments.readAll().split('\n')) {
            const QJsonObject record = QJsonDocument::fromJson(line).object();
            if (record.value(QStringLiteral("id")).toString() == QLatin1String("delta-primary")) found = record;
        }
        comments.close();
        return found;
    };
    QJsonObject orphanedPrimary = primaryRecord();
    QVERIFY(!orphanedPrimary.isEmpty());
    QVERIFY2(!orphanedPrimary.value(QStringLiteral("deleted")).toBool(), QJsonDocument(orphanedPrimary).toJson().constData());
    QCOMPARE(orphanedPrimary.value(QStringLiteral("anchor_status")).toString(), QStringLiteral("orphaned"));
    QCOMPARE(orphanedPrimary.value(QStringLiteral("orphan_reason")).toString(), QStringLiteral("anchor_removed"));
    QVERIFY(!orphanedPrimary.value(QStringLiteral("orphaned_at")).toString().isEmpty());
    QCOMPARE(orphanedPrimary.value(QStringLiteral("tex_file")).toString(), QStringLiteral("docs-one/src/moved.tex"));
    QVERIFY(!orphanedPrimary.contains(QStringLiteral("source_anchor_deletion")) && !orphanedPrimary.contains(QStringLiteral("deletion_reason")));
    QFile state(root.filePath(QStringLiteral("comments/.state/open.json")));
    QVERIFY(state.open(QIODevice::ReadOnly));
    QVERIFY(!state.readAll().contains("source_anchor_removed"));
    state.close();

    // A later PDF edit of the anchor-removed comment is an ordinary edit: it
    // keeps the orphaned placement and never re-inserts a marker.
    primaryComment.insert(QStringLiteral("contents"), QStringLiteral("edited while anchor removed"));
    primaryComment.insert(QStringLiteral("modified"), QStringLiteral("D:20260728120600+02'00'"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.anchorAttempts, 0);
    QCOMPARE(result.sourceAnchorsOrphaned, 0);
    orphanedPrimary = primaryRecord();
    QCOMPARE(orphanedPrimary.value(QStringLiteral("contents")).toString(), QStringLiteral("edited while anchor removed"));
    QCOMPARE(orphanedPrimary.value(QStringLiteral("anchor_status")).toString(), QStringLiteral("orphaned"));
    QCOMPARE(orphanedPrimary.value(QStringLiteral("orphan_reason")).toString(), QStringLiteral("anchor_removed"));
    {
        QFile moved(movedSourcePath);
        QVERIFY(moved.open(QIODevice::ReadOnly));
        QCOMPARE(moved.readAll(), QByteArray("Moved target sentence.\n"));
    }
    QFile resolutionRegistry(root.filePath(QStringLiteral("comments/review_resolutions.jsonl")));
    QVERIFY(!resolutionRegistry.open(QIODevice::ReadOnly) || !resolutionRegistry.readAll().contains("\"source_anchor_deletion\":true"));
    resolutionRegistry.close();

    // The marker reappearing re-anchors the placement and clears the orphan reason.
    QVERIFY(writeFile(movedSourcePath, markerLine + "\nMoved target sentence.\n"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {primaryComment}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    orphanedPrimary = primaryRecord();
    QCOMPARE(orphanedPrimary.value(QStringLiteral("anchor_status")).toString(), QStringLiteral("anchored"));
    QVERIFY(!orphanedPrimary.contains(QStringLiteral("orphan_reason")) && !orphanedPrimary.contains(QStringLiteral("orphaned_at")));

    // An explicit PDF deletion while the marker also disappears stays an
    // ordinary user tombstone (explicit delete wins over anchor removal).
    QVERIFY(writeFile(movedSourcePath, "Moved target sentence.\n"));
    result = synchronizer.synchronize(QUrl::fromLocalFile(pdfPath), makeSnapshot(QJsonArray {}));
    QVERIFY2(result.success, qPrintable(result.failureReason));
    QCOMPARE(result.sourceAnchorDeletions, 0);
    QCOMPARE(result.sourceAnchorsOrphaned, 0);
    const QJsonObject deletedPrimary = primaryRecord();
    QVERIFY2(deletedPrimary.value(QStringLiteral("deleted")).toBool(), QJsonDocument(deletedPrimary).toJson().constData());
    QVERIFY(!deletedPrimary.contains(QStringLiteral("source_anchor_deletion")));
    QVERIFY(!deletedPrimary.contains(QStringLiteral("deletion_reason")));
    QVERIFY(state.open(QIODevice::ReadOnly));
    QVERIFY(!state.readAll().contains("source_anchor_deletion"));
    state.close();
}

void PartTest::testDocsPointCommentRetriesAfterSourceRestored()
{
#ifdef Q_OS_WIN
    QSKIP("This test runs POSIX shell scripts as helpers.");
#endif
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments/.layout")));
    QVERIFY(root.mkpath(QStringLiteral("docs-one/tex/source")));
    QVERIFY(root.mkpath(QStringLiteral(".runtime/comment_anchors/builds/build-id/sources")));
    QVERIFY(root.mkpath(QStringLiteral(".runtime/comment_anchors/published")));

    const auto writeFile = [](const QString &path, const QByteArray &contents) {
        QFile file(path);
        return file.open(QIODevice::WriteOnly | QIODevice::Truncate) && file.write(contents) == contents.size();
    };
    const QString pdfPath = root.filePath(QStringLiteral("current_pdfs/open.pdf"));
    const QString exactPdfPath = root.filePath(QStringLiteral("exact-pdf-object"));
    const QString cachedPdfPath = root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/document.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), pdfPath));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), exactPdfPath));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), cachedPdfPath));

    const QByteArray historicalSource =
        "\\documentclass{article}\n"
        "\\begin{document}\n"
        "Historical paragraph before.\n"
        "Anchor target sentence.\n"
        "Historical paragraph after.\n"
        "\\end{document}\n";
    const QByteArray conflictingSource =
        "\\documentclass{article}\n"
        "\\begin{document}\n"
        "Conflicting paragraph before.\n"
        "Different unrelated sentence.\n"
        "Conflicting paragraph after.\n"
        "\\end{document}\n";
    const QString sourcePath = root.filePath(QStringLiteral("docs-one/tex/source/main.tex"));
    QVERIFY(writeFile(sourcePath, conflictingSource));
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/sources/0000.tex")), historicalSource));
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/document.synctex.gz")), "test"));
    QVERIFY(writeFile(root.filePath(QStringLiteral("comments/.layout/open.json")),
                      "{\"version\":1,\"page_count\":1,\"sources\":[{\"fingerprint\":\"source-fingerprint\","
                      "\"page_count\":1,\"source_id\":\"docs-one/tex/source/main.tex\",\"start_page\":1}]}"));

    const QJsonObject mapping {
        {QStringLiteral("version"), 2},
        {QStringLiteral("build_id"), QStringLiteral("build-id")},
        {QStringLiteral("pdf_name"), QStringLiteral("document.pdf")},
        {QStringLiteral("source_fingerprint"), QStringLiteral("source-fingerprint")},
        {QStringLiteral("source_id"), QStringLiteral("docs-one/tex/source/main.tex")},
        {QStringLiteral("source_tex_absolute"), sourcePath},
        {QStringLiteral("synctex_fingerprint"), QStringLiteral("synctex-fingerprint")},
        {QStringLiteral("synctex_name"), QStringLiteral("document.synctex.gz")},
        {QStringLiteral("source_snapshots"),
         QJsonArray {
             QJsonObject {
                 {QStringLiteral("source_id"), QStringLiteral("docs-one/tex/source/main.tex")},
                 {QStringLiteral("source_tex_absolute"), sourcePath},
                 {QStringLiteral("snapshot"), QStringLiteral("sources/0000.tex")},
                 {QStringLiteral("input_order"), 0},
                 {QStringLiteral("marker_eligible"), true},
             },
         }},
    };
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/builds/build-id/mapping.json")), QJsonDocument(mapping).toJson(QJsonDocument::Compact)));

    QFile exactPdf(exactPdfPath);
    QVERIFY(exactPdf.open(QIODevice::ReadOnly));
    const QString exactPdfSha256 = QString::fromLatin1(QCryptographicHash::hash(exactPdf.readAll(), QCryptographicHash::Sha256).toHex());
    exactPdf.close();
    const QJsonObject provenance {
        {QStringLiteral("version"), 1},
        {QStringLiteral("pdf_filename"), QStringLiteral("open.pdf")},
        {QStringLiteral("pdf_sha256"), exactPdfSha256},
        {QStringLiteral("page_count"), 1},
        {QStringLiteral("pages"),
         QJsonArray {
             QJsonObject {
                 {QStringLiteral("page"), 1},
                 {QStringLiteral("source_id"), QStringLiteral("docs-one/tex/source/main.tex")},
                 {QStringLiteral("source_build_id"), QStringLiteral("build-id")},
                 {QStringLiteral("local_page"), 1},
             },
         }},
    };
    QVERIFY(writeFile(root.filePath(QStringLiteral(".runtime/comment_anchors/published/") + exactPdfSha256 + QStringLiteral(".json")), QJsonDocument(provenance).toJson(QJsonDocument::Compact)));

    const QJsonObject comment {
        {QStringLiteral("schema_version"), 5},
        {QStringLiteral("id"), QStringLiteral("stale-point")},
        {QStringLiteral("annotation_id"), QStringLiteral("stale-point")},
        {QStringLiteral("annotation_pdf_sha256"), exactPdfSha256},
        {QStringLiteral("page"), 1},
        {QStringLiteral("subtype"), QStringLiteral("Text")},
        {QStringLiteral("rect"), QJsonArray {61.2, 673.2, 122.4, 712.8}},
        {QStringLiteral("contents"), QStringLiteral("review this point")},
        {QStringLiteral("created"), QStringLiteral("D:20260830205410+02'00'")},
        {QStringLiteral("updated_at"), QStringLiteral("2026-08-30T18:54:11.019Z")},
        {QStringLiteral("revision"), 1},
    };
    QVERIFY(writeFile(root.filePath(QStringLiteral("comments/open_comments.jsonl")), QJsonDocument(comment).toJson(QJsonDocument::Compact) + '\n'));

    const QString synctexPath = root.filePath(QStringLiteral("fake-synctex.sh"));
    const QByteArray synctexScript = QByteArray("#!/bin/bash\ncat <<'EOF'\nSyncTeX result begin\nInput:") + sourcePath.toUtf8() + "\nLine:4\nColumn:1\nSyncTeX result end\nEOF\n";
    QVERIFY(writeFile(synctexPath, synctexScript));
    QVERIFY(QFile::setPermissions(synctexPath, QFileDevice::ReadOwner | QFileDevice::WriteOwner | QFileDevice::ExeOwner));

    DocsCommentSynchronizer synchronizer({
        .docsRoot = docsRoot.path(),
        .synctexExecutable = synctexPath,
        .processEnvironment = QProcessEnvironment::systemEnvironment(),
    });
    const auto geometry = [](const QString &, int pageNumber, QString *) -> std::optional<DocsCommentSynchronizer::PageGeometry> {
        if (pageNumber != 1) {
            return std::nullopt;
        }
        return DocsCommentSynchronizer::PageGeometry {.width = 612.0, .height = 792.0, .rotation = 0};
    };
    const DocsCommentSynchronizer::Result blocked = synchronizer.prepareAnnotation(QStringLiteral("open"), QStringLiteral("stale-point"), geometry, exactPdfPath);
    QVERIFY2(blocked.success, qPrintable(blocked.failureReason));
    QCOMPARE(blocked.anchorsInserted, 0);
    QFile source(sourcePath);
    QVERIFY(source.open(QIODevice::ReadOnly));
    QVERIFY(!source.readAll().contains("\\CommentAnchor{stale-point}"));
    source.close();

    QVERIFY(writeFile(sourcePath, historicalSource));
    const DocsCommentSynchronizer::Result retried = synchronizer.prepareAnnotation(QStringLiteral("open"), QStringLiteral("stale-point"), geometry, exactPdfPath);
    QVERIFY2(retried.success, qPrintable(retried.failureReason));
    QCOMPARE(retried.anchorsInserted, 1);
    QVERIFY(source.open(QIODevice::ReadOnly));
    const QByteArray anchored = source.readAll();
    QVERIFY2(anchored.contains("\\CommentAnchor{stale-point}{review this point}%\nAnchor target sentence."), anchored.constData());
    source.close();
    QFile sidecar(root.filePath(QStringLiteral("comments/open_comments.jsonl")));
    QVERIFY(sidecar.open(QIODevice::ReadOnly));
    const QByteArray stored = sidecar.readAll();
    QVERIFY(stored.contains("\"anchor_status\":\"anchored\""));
    QVERIFY(stored.contains("\"tex_file\":\"docs-one/tex/source/main.tex\""));
}

void PartTest::testCommentHighlightProposalVisibility()
{
    const QString source = QStringLiteral("\\agentProposedEdit[created=2026-10-10T12:00:00.000Z,conversation_id=0b6c5b7e-1d2a-4c3b-9f8e-112233445566]{migration}{reason}\n"
        "{\\CommentAnchor{same}{old}{word}}\n"
        "{\\CommentHighlight{same}{new}{word}}\n"
        "\\CommentAnchor{point}{standalone}\n"
        "\\code{\\CommentHighlight{example}{note}{word}}\n");
    const QString visible = visibleCommentSource(source);
    QCOMPARE(visible.size(), source.size());
    QCOMPARE(visible.count(QLatin1Char('\n')), source.count(QLatin1Char('\n')));
    QVERIFY(!visible.contains(QStringLiteral("{old}")));
    QVERIFY(!visible.contains(QStringLiteral("{example}")));
    QVERIFY(visible.contains(QStringLiteral("\\CommentHighlight{same}{new}{word}")));
    QVERIFY(visible.contains(QStringLiteral("\\CommentAnchor{point}{standalone}")));
}

