    const QJsonObject markup {
        {QStringLiteral("schema_version"), 5},
        {QStringLiteral("id"), QStringLiteral("skipped-markup")},
        {QStringLiteral("review_key"), QStringLiteral("id:skipped-markup")},
        {QStringLiteral("revision"), 1},
        {QStringLiteral("updated_at"), QStringLiteral("2026-08-10T10:00:00.000Z")},
        {QStringLiteral("origin_id"), QStringLiteral("android-mj-pdf")},
        {QStringLiteral("page"), 99},
        {QStringLiteral("subtype"), QStringLiteral("Highlight")},
        {QStringLiteral("rect"), QJsonArray {60, 60, 100, 100}},
        {QStringLiteral("contents"), QString()},
        {QStringLiteral("selected_text"), QString()},
        {QStringLiteral("source_pdf"), skippedPdf},
        {QStringLiteral("flags"), 4},
        {QStringLiteral("opacity"), 1},
    };
    QFile sidecar(root.filePath(QStringLiteral("comments/skipped_comments.jsonl")));
