    QVERIFY(sidecar.write(QJsonDocument(markup).toJson(QJsonDocument::Compact) + '\n') > 0);
    sidecar.close();

    DocsCommentSynchronizer synchronizer({
        .docsRoot = docsRoot.path(),
        .processEnvironment = QProcessEnvironment::systemEnvironment(),
        .lockTimeoutMs = 2000,
    });
    bool geometryCalled = false;
