void PartTest::testDocsCommentSyncExistingJsonGeometryBenchmark()
{
    const QString sourcePdf = qEnvironmentVariable("OKULAR_SAVE_BENCHMARK_PDF");
    if (sourcePdf.isEmpty()) {
        QSKIP("Set OKULAR_SAVE_BENCHMARK_PDF to verify native geometry against an existing canonical JSONL file.");
    }
    const QFileInfo pdfInfo(sourcePdf);
    QDir docsRoot = pdfInfo.absoluteDir();
    QVERIFY2(docsRoot.cdUp(), qPrintable(sourcePdf));
    const QString stem = pdfInfo.completeBaseName().section(QStringLiteral(".sync-conflict"), 0, 0);
    const QString canonicalPath = docsRoot.filePath(QStringLiteral("comments/%1_comments.jsonl").arg(stem));
    QVERIFY2(QFileInfo::exists(canonicalPath), qPrintable(canonicalPath));

    Okular::Part part(nullptr, {});
    QVERIFY(openDocument(&part, sourcePdf));
    QJsonObject snapshot;
    QString failure;
    QElapsedTimer timer;
    timer.start();
    QVERIFY2(part.writeDocsCommentSnapshot(QUrl::fromLocalFile(sourcePdf), &snapshot, &failure), qPrintable(failure));
    const qint64 snapshotMs = timer.elapsed();

    QHash<QString, QJsonObject> canonicalById;
    QFile canonicalFile(canonicalPath);
    QVERIFY(canonicalFile.open(QIODevice::ReadOnly | QIODevice::Text));
    while (!canonicalFile.atEnd()) {
        const QJsonDocument document = QJsonDocument::fromJson(canonicalFile.readLine());
        if (document.isObject()) {
            const QJsonObject comment = document.object();
            const QString id = comment.value(QStringLiteral("id")).toString();
            if (!id.isEmpty()) {
                canonicalById.insert(id, comment);
            }
        }
    }

    const auto pdfRect = [](const QJsonObject &raw) {
        const QJsonArray rect = raw.value(QStringLiteral("rect")).toArray();
        const double width = raw.value(QStringLiteral("page_width")).toDouble();
        const double height = raw.value(QStringLiteral("page_height")).toDouble();
        const double x0 = rect.at(0).toDouble() * width;
        const double y0 = (1.0 - rect.at(1).toDouble()) * height;
        const double x1 = rect.at(2).toDouble() * width;
        const double y1 = (1.0 - rect.at(3).toDouble()) * height;
        return QJsonArray {std::min(x0, x1), std::min(y0, y1), std::max(x0, x1), std::max(y0, y1)};
    };
    const auto pdfQuads = [](const QJsonObject &raw) -> QJsonValue {
        if (!raw.value(QStringLiteral("quad_points")).isArray()) {
            return QJsonValue::Null;
        }
        const double width = raw.value(QStringLiteral("page_width")).toDouble();
        const double height = raw.value(QStringLiteral("page_height")).toDouble();
        QJsonArray result;
        const QJsonArray points = raw.value(QStringLiteral("quad_points")).toArray();
        for (qsizetype index = 0; index + 1 < points.size(); index += 2) {
            result.append(points.at(index).toDouble() * width);
            result.append((1.0 - points.at(index + 1).toDouble()) * height);
        }
        return result;
    };
    const auto sameNumbers = [](const QJsonValue &left, const QJsonValue &right) {
        if (left.isNull() || right.isNull()) {
            return left.isNull() && right.isNull();
        }
        const QJsonArray leftArray = left.toArray();
        const QJsonArray rightArray = right.toArray();
        if (leftArray.size() != rightArray.size()) {
            return false;
        }
        for (qsizetype index = 0; index < leftArray.size(); ++index) {
            if (qRound64(leftArray.at(index).toDouble() * 1000000.0) != qRound64(rightArray.at(index).toDouble() * 1000000.0)) {
                return false;
            }
        }
        return true;
    };

    int matched = 0;
    int unmatched = 0;
    int geometryMismatches = 0;
    for (const QJsonValue &value : snapshot.value(QStringLiteral("comments")).toArray()) {
        const QJsonObject raw = value.toObject();
        const QString id = raw.value(QStringLiteral("id")).toString();
        if (id.isEmpty() || !canonicalById.contains(id)) {
            ++unmatched;
            continue;
        }
        ++matched;
        const QJsonObject previous = canonicalById.value(id);
        if (raw.value(QStringLiteral("page")).toInt() != previous.value(QStringLiteral("page")).toInt() || raw.value(QStringLiteral("subtype")).toString() != previous.value(QStringLiteral("subtype")).toString() ||
            !sameNumbers(pdfRect(raw), previous.value(QStringLiteral("rect"))) || !sameNumbers(pdfQuads(raw), previous.value(QStringLiteral("quad_points")))) {
            ++geometryMismatches;
            if (geometryMismatches == 1) {
                qWarning().noquote() << "native-geometry-mismatch" << id << "snapshot-page" << raw.value(QStringLiteral("page")) << "canonical-page" << previous.value(QStringLiteral("page")) << "snapshot-subtype"
                                     << raw.value(QStringLiteral("subtype")) << "canonical-subtype" << previous.value(QStringLiteral("subtype")) << "snapshot-rect" << QJsonDocument(pdfRect(raw)).toJson(QJsonDocument::Compact)
                                     << "canonical-rect" << QJsonDocument(previous.value(QStringLiteral("rect")).toArray()).toJson(QJsonDocument::Compact) << "snapshot-quads"
                                     << QJsonDocument(pdfQuads(raw).toArray()).toJson(QJsonDocument::Compact) << "canonical-quads" << QJsonDocument(previous.value(QStringLiteral("quad_points")).toArray()).toJson(QJsonDocument::Compact);
            }
        }
    }
    qInfo().noquote() << "native-json-geometry-benchmark" << QStringLiteral("source=") + sourcePdf << QStringLiteral("comments=") + QString::number(snapshot.value(QStringLiteral("comments")).toArray().size())
                      << QStringLiteral("matched=") + QString::number(matched) << QStringLiteral("unmatched=") + QString::number(unmatched) << QStringLiteral("geometry-mismatches=") + QString::number(geometryMismatches)
                      << QStringLiteral("snapshot-ms=") + QString::number(snapshotMs);
    QVERIFY(matched > 0);
    QCOMPARE(geometryMismatches, 0);
}

void PartTest::testDocsCommentSyncRealWorldSaveBenchmark()
{
    const QString sourcePdf = qEnvironmentVariable("OKULAR_SAVE_BENCHMARK_PDF");
    if (sourcePdf.isEmpty()) {
        QSKIP("Set OKULAR_SAVE_BENCHMARK_PDF to run the real-world native synchronization benchmark.");
    }
    const QFileInfo sourcePdfInfo(sourcePdf);
    QDir sourceDocsRoot = sourcePdfInfo.absoluteDir();
    QVERIFY2(sourceDocsRoot.cdUp(), qPrintable(sourcePdf));
    const QString stem = sourcePdfInfo.completeBaseName();

    const QTemporaryDir temporaryDirectory;
    QVERIFY(temporaryDirectory.isValid());
    QDir targetRoot(temporaryDirectory.path());
    QVERIFY(targetRoot.mkpath(QStringLiteral("current_pdfs")));
    const QString targetPdf = targetRoot.filePath(QStringLiteral("current_pdfs/") + sourcePdfInfo.fileName());
    QVERIFY(QFile::copy(sourcePdf, targetPdf));

    const auto copyRelative = [&sourceDocsRoot, &targetRoot](const QString &relativePath, bool required = false) {
        const QString source = sourceDocsRoot.filePath(relativePath);
        if (!QFileInfo::exists(source)) {
            return !required;
        }
        const QString target = targetRoot.filePath(relativePath);
        if (!QDir().mkpath(QFileInfo(target).absolutePath())) {
            return false;
        }
        return QFileInfo::exists(target) || QFile::copy(source, target);
    };
    const QString canonicalRelative = QStringLiteral("comments/%1_comments.jsonl").arg(stem);
    QVERIFY(copyRelative(canonicalRelative, true));
    QVERIFY(copyRelative(QStringLiteral("comments/.state/%1.json").arg(stem)));
    QVERIFY(copyRelative(QStringLiteral("comments/review_resolutions.jsonl")));
    QVERIFY(copyRelative(QStringLiteral("comments/.layout/%1.json").arg(stem)));

    QSet<QString> sourceFiles;
    QFile canonical(sourceDocsRoot.filePath(canonicalRelative));
    QVERIFY(canonical.open(QIODevice::ReadOnly | QIODevice::Text));
    while (!canonical.atEnd()) {
        const QJsonDocument document = QJsonDocument::fromJson(canonical.readLine());
        const QString texFile = document.object().value(QStringLiteral("tex_file")).toString();
        if (!texFile.isEmpty() && !QFileInfo(texFile).isAbsolute()) {
            sourceFiles.insert(texFile);
        }
    }
    QFile layout(sourceDocsRoot.filePath(QStringLiteral("comments/.layout/%1.json").arg(stem)));
    if (layout.open(QIODevice::ReadOnly)) {
        for (const QJsonValue &value : QJsonDocument::fromJson(layout.readAll()).object().value(QStringLiteral("sources")).toArray()) {
            const QString sourceId = value.toObject().value(QStringLiteral("source_id")).toString();
            if (sourceId.endsWith(QLatin1String(".tex"))) {
                sourceFiles.insert(sourceId);
            }
        }
    }
    for (const QString &sourceFile : std::as_const(sourceFiles)) {
        QVERIFY2(copyRelative(sourceFile), qPrintable(sourceFile));
    }

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = temporaryDirectory.path();
    QVERIFY(openDocument(&part, targetPdf));
    QElapsedTimer timer;
    timer.start();
    QVERIFY(part.saveAs(QUrl::fromLocalFile(targetPdf)));
    const qint64 elapsedMs = timer.elapsed();

    QFile log(part.m_docsCommentSyncLogPath);
    QVERIFY(log.open(QIODevice::ReadOnly));
    const QByteArray output = log.readAll();
    QVERIFY2(output.contains("anchor-candidates=0"), output.constData());
    QVERIFY2(output.contains("anchor-attempts=0"), output.constData());
    qInfo().noquote() << "native-real-world-save-benchmark" << QStringLiteral("source=") + sourcePdf << QStringLiteral("pages=") + QString::number(part.m_document->pages()) << QStringLiteral("elapsed-ms=") + QString::number(elapsedMs)
                      << QString::fromUtf8(output).simplified();
}

