void PartTest::testAnnotationSidebarUsesSourceCommentProjection()
{
    Okular::Settings::setGroupByAuthor(false);
    Okular::Settings::setGroupByPage(false);
    Okular::Settings::setCurrentPageOnly(false);

    Okular::Part part(nullptr, {});
    QVERIFY(openDocument(&part, QStringLiteral(KDESRCDIR "data/file1.pdf")));
    auto *annotation = new Okular::TextAnnotation();
    annotation->setTextType(Okular::TextAnnotation::Linked);
    annotation->setUniqueName(QStringLiteral("source-comment-id"));
    annotation->setBoundingRectangle(Okular::NormalizedRect(0.2, 0.2, 0.25, 0.25));
    annotation->setContents(QStringLiteral("Canonical comment"));
    part.m_document->addPageAnnotation(0, annotation);

    auto *model = static_cast<AnnotationModel *>(part.annotationsModel());
    QVERIFY(model);
    QTRY_COMPARE(model->rowCount(), 1);
    model->setSourceComments({
        {
            QStringLiteral("source-comment-id"),
            QStringLiteral("Current source comment"),
            QStringLiteral("docs-benchmark/tex/source/main.tex"),
            42,
        },
    });

    QModelIndex row = model->index(0, 0);
    while (row.isValid() && !model->isAnnotation(row)) {
        row = model->index(0, 0, row);
    }
    QVERIFY(row.isValid());
    // The text follows the canonical comment shown in the PDF; the source
    // projection adds the comment's source location.
    QCOMPARE(row.data().toString(), QStringLiteral("Canonical comment"));
    QVERIFY(row.data(Qt::ToolTipRole).toString().contains(QStringLiteral("docs-benchmark/tex/source/main.tex:42")));
}

