void PartTest::testCommentsOverviewMutationsPersist()
{
    const QTemporaryDir temporary;
    QVERIFY(temporary.isValid());
    const QString pdfPath = QDir(temporary.path()).filePath(QStringLiteral("overview-mutations.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/simple-multipage.pdf"), pdfPath));

    Okular::Part part(nullptr, {});
    QVERIFY(openDocument(&part, pdfPath));
    // Unmanaged documents are read-only in the app; this engine fixture
    // enables annotation editing explicitly.
    part.m_document->setAnnotationEditingEnabled(true);

    const auto makeHighlight = [](const QString &id, const QString &contents, const Okular::NormalizedRect &rect) {
        auto *annotation = new Okular::HighlightAnnotation();
        annotation->setUniqueName(id);
        annotation->setContents(contents);
        annotation->setBoundingRectangle(rect);
        Okular::HighlightAnnotation::Quad quad;
        quad.setPoint(Okular::NormalizedPoint(rect.left, rect.bottom), 0);
        quad.setPoint(Okular::NormalizedPoint(rect.right, rect.bottom), 1);
        quad.setPoint(Okular::NormalizedPoint(rect.right, rect.top), 2);
        quad.setPoint(Okular::NormalizedPoint(rect.left, rect.top), 3);
        annotation->highlightQuads().append(quad);
        return annotation;
    };

    const QString logicalId = QStringLiteral("overview-logical-comment");
    Okular::HighlightAnnotation *root = makeHighlight(logicalId, QStringLiteral("Original grouped comment"), Okular::NormalizedRect(0.1, 0.8, 0.9, 0.9));
    Okular::HighlightAnnotation *continuation = makeHighlight(Thoughts::makeCommentFragmentId(logicalId, 1), QStringLiteral("Original grouped comment"), Okular::NormalizedRect(0.1, 0.1, 0.9, 0.2));
    part.m_document->addPageAnnotation(0, root);
    part.m_document->addPageAnnotation(1, continuation);
    QVERIFY(part.saveFile());
    part.m_document->clearHistory();

    const auto verifyPersisted = [&pdfPath, &logicalId](const QString &rootContents, const QString &continuationContents, int annotationCount) {
        Okular::Part reopened(nullptr, {});
        if (!openDocument(&reopened, pdfPath)) {
            return false;
        }
        int count = 0;
        QString persistedRootContents;
        QString persistedContinuationContents;
        for (uint pageNumber = 0; pageNumber < reopened.m_document->pages(); ++pageNumber) {
            for (Okular::Annotation *annotation : reopened.m_document->page(pageNumber)->annotations()) {
                if (annotation->uniqueName() == logicalId) {
                    persistedRootContents = annotation->contents();
                    ++count;
                } else if (annotation->uniqueName() == Thoughts::makeCommentFragmentId(logicalId, 1)) {
                    persistedContinuationContents = annotation->contents();
                    ++count;
                }
            }
        }
        return count == annotationCount && persistedRootContents == rootContents && persistedContinuationContents == continuationContents;
    };

    QVariantMap result = part.editReviewAnnotation(QStringLiteral("id:") + logicalId, 99, QStringLiteral("Edited grouped comment"));
    QVERIFY2(result.value(QStringLiteral("success")).toBool(), qPrintable(result.value(QStringLiteral("error")).toString()));
    QCOMPARE(root->contents(), QStringLiteral("Edited grouped comment"));
    QVERIFY(continuation->contents().isEmpty());
    QVERIFY(result.value(QStringLiteral("canUndo")).toBool());
    QVERIFY(verifyPersisted(QStringLiteral("Edited grouped comment"), QString(), 2));

    result = part.undoReviewChange();
    QVERIFY2(result.value(QStringLiteral("success")).toBool(), qPrintable(result.value(QStringLiteral("error")).toString()));
    QCOMPARE(root->contents(), QStringLiteral("Original grouped comment"));
    QCOMPARE(continuation->contents(), QStringLiteral("Original grouped comment"));
    QVERIFY(result.value(QStringLiteral("canRedo")).toBool());
    QVERIFY(verifyPersisted(QStringLiteral("Original grouped comment"), QStringLiteral("Original grouped comment"), 2));

    result = part.redoReviewChange();
    QVERIFY2(result.value(QStringLiteral("success")).toBool(), qPrintable(result.value(QStringLiteral("error")).toString()));
    QCOMPARE(root->contents(), QStringLiteral("Edited grouped comment"));
    QVERIFY(continuation->contents().isEmpty());
    QVERIFY(!result.value(QStringLiteral("canRedo")).toBool());
    QVERIFY(verifyPersisted(QStringLiteral("Edited grouped comment"), QString(), 2));

    result = part.deleteReviewAnnotation(logicalId, 1);
    QVERIFY2(result.value(QStringLiteral("success")).toBool(), qPrintable(result.value(QStringLiteral("error")).toString()));
    QCOMPARE(part.m_document->page(0)->annotations().size(), 0);
    QCOMPARE(part.m_document->page(1)->annotations().size(), 0);
    QVERIFY(verifyPersisted(QString(), QString(), 0));

    result = part.undoReviewChange();
    QVERIFY2(result.value(QStringLiteral("success")).toBool(), qPrintable(result.value(QStringLiteral("error")).toString()));
    QCOMPARE(part.m_document->page(0)->annotations().size(), 1);
    QCOMPARE(part.m_document->page(1)->annotations().size(), 1);
    QVERIFY(verifyPersisted(QStringLiteral("Edited grouped comment"), QString(), 2));

    auto *unrelated = new Okular::TextAnnotation();
    unrelated->setBoundingRectangle(Okular::NormalizedRect(0.2, 0.3, 0.3, 0.4));
    unrelated->setContents(QStringLiteral("Unrelated PDF edit"));
    part.m_document->addPageAnnotation(0, unrelated);
    result = part.undoReviewChange();
    QVERIFY(!result.value(QStringLiteral("success")).toBool());
    QVERIFY(result.value(QStringLiteral("historyReset")).toBool());
    QVERIFY(!result.value(QStringLiteral("canUndo")).toBool());
    QVERIFY(!result.value(QStringLiteral("canRedo")).toBool());
    QCOMPARE(part.m_document->page(0)->annotations().size(), 2);
    QCOMPARE(unrelated->contents(), QStringLiteral("Unrelated PDF edit"));
}

void PartTest::testDocsCommentMutationsDoNotWriteReadOnlyPdf()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString pdfPath = root.filePath(QStringLiteral("read-only.pdf"));
    const QString managedPdfPath = root.filePath(QStringLiteral("current_pdfs/read-only.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/simple-multipage.pdf"), pdfPath));
    QVERIFY(QFile::rename(pdfPath, managedPdfPath));
    QVERIFY(registerLibraryPdf(root.path(), managedPdfPath));
    const QFileDevice::Permissions readOnlyPermissions = QFileDevice::ReadOwner | QFileDevice::ReadGroup | QFileDevice::ReadOther;
    QVERIFY(QFile::setPermissions(managedPdfPath, readOnlyPermissions));

    const auto digest = [&managedPdfPath] {
        QFile file(managedPdfPath);
        if (!file.open(QIODevice::ReadOnly)) {
            return QByteArray {};
        }
        QCryptographicHash hash(QCryptographicHash::Sha256);
        return hash.addData(&file) ? hash.result() : QByteArray {};
    };
    const QByteArray before = digest();
    QVERIFY(!before.isEmpty());

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(openDocument(&part, managedPdfPath));
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 2000);
    QTRY_VERIFY_WITH_TIMEOUT(!part.m_docsCommentFingerprint.isEmpty(), 3000);

    auto *annotation = new Okular::TextAnnotation();
    annotation->setTextType(Okular::TextAnnotation::Linked);
    annotation->setUniqueName(QStringLiteral("read-only-comment"));
    annotation->setBoundingRectangle(Okular::NormalizedRect(0.2, 0.2, 0.25, 0.25));
    annotation->setContents(QStringLiteral("Sidecar only"));
    part.m_document->addPageAnnotation(0, annotation);
    QTRY_VERIFY_WITH_TIMEOUT(!part.isModified(), 2000);
    QTRY_COMPARE_WITH_TIMEOUT(DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("read-only"), nullptr, nullptr).size(), 1, 3000);

    const QVariantMap deleted = part.deleteReviewAnnotation(QStringLiteral("read-only-comment"), 1);
    QVERIFY2(deleted.value(QStringLiteral("success")).toBool(), qPrintable(deleted.value(QStringLiteral("error")).toString()));
    QTRY_COMPARE_WITH_TIMEOUT(DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("read-only"), nullptr, nullptr).size(), 0, 3000);

    auto *highlight = new Okular::HighlightAnnotation();
    highlight->setUniqueName(QStringLiteral("read-only-highlight"));
    highlight->setContents(QStringLiteral("Highlighted sidecar comment"));
    const Okular::NormalizedRect highlightRect(0.1, 0.1, 0.5, 0.15);
    highlight->setBoundingRectangle(highlightRect);
    Okular::HighlightAnnotation::Quad quad;
    quad.setPoint(Okular::NormalizedPoint(highlightRect.left, highlightRect.bottom), 0);
    quad.setPoint(Okular::NormalizedPoint(highlightRect.right, highlightRect.bottom), 1);
    quad.setPoint(Okular::NormalizedPoint(highlightRect.right, highlightRect.top), 2);
    quad.setPoint(Okular::NormalizedPoint(highlightRect.left, highlightRect.top), 3);
    highlight->highlightQuads().append(quad);
    part.m_document->addPageAnnotation(0, highlight);
    QTRY_COMPARE_WITH_TIMEOUT(DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("read-only"), nullptr, nullptr).size(), 1, 3000);
    QVERIFY(!part.isModified());
    part.m_document->undo();
    QTRY_COMPARE_WITH_TIMEOUT(DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("read-only"), nullptr, nullptr).size(), 0, 3000);
    QVERIFY(!part.isModified());
    part.m_document->redo();
    QTRY_COMPARE_WITH_TIMEOUT(DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("read-only"), nullptr, nullptr).size(), 1, 3000);

    QCOMPARE(digest(), before);
    QVERIFY(!(QFileInfo(managedPdfPath).permissions() & QFileDevice::WriteOwner));
    QVERIFY(!part.isModified());
}

void PartTest::testDocsCommentReplyCreation()
{
    const QTemporaryDir docsRoot;
    QVERIFY(docsRoot.isValid());
    QDir root(docsRoot.path());
    QVERIFY(root.mkpath(QStringLiteral("current_pdfs")));
    QVERIFY(root.mkpath(QStringLiteral("comments")));
    const QString managedPdfPath = root.filePath(QStringLiteral("current_pdfs/replies.pdf"));
    QVERIFY(QFile::copy(QStringLiteral(KDESRCDIR "data/file1.pdf"), managedPdfPath));
    QVERIFY(registerLibraryPdf(root.path(), managedPdfPath));

    Okular::Part part(nullptr, {});
    part.m_docsRenderRoot = docsRoot.path();
    QVERIFY(openDocument(&part, managedPdfPath));
    part.widget()->show();
    QTRY_VERIFY_WITH_TIMEOUT(part.m_docsOpenedPdfIdentityVerified, 2000);
    QTRY_VERIFY_WITH_TIMEOUT(!part.m_docsCommentFingerprint.isEmpty(), 3000);

    auto *rootAnnotation = new Okular::TextAnnotation();
    rootAnnotation->setTextType(Okular::TextAnnotation::Linked);
    rootAnnotation->setTextIcon(QStringLiteral("Comment"));
    rootAnnotation->setUniqueName(QStringLiteral("reply-root"));
    rootAnnotation->setBoundingRectangle(Okular::NormalizedRect(0.2, 0.2, 0.25, 0.25));
    rootAnnotation->setContents(QStringLiteral("Root comment"));
    rootAnnotation->setAuthor(QStringLiteral("Root author"));
    rootAnnotation->style().setColor(Qt::yellow);
    part.m_document->addPageAnnotation(0, rootAnnotation);

    const QVariantMap result = part.addReviewAnnotationReply(QStringLiteral("id:reply-root"), 1, QStringLiteral("  Desktop reply  "));
    QVERIFY2(result.value(QStringLiteral("success")).toBool(), qPrintable(result.value(QStringLiteral("error")).toString()));
    const QString replyId = result.value(QStringLiteral("replyId")).toString();
    QVERIFY(replyId.startsWith(QStringLiteral("thoughts-")));
    Okular::Annotation *replyAnnotation = part.m_document->page(0)->annotation(replyId);
    QVERIFY(replyAnnotation);
    QCOMPARE(replyAnnotation->contents(), QStringLiteral("Desktop reply"));
    QCOMPARE(replyAnnotation->previousAnnotation(), rootAnnotation);
    QCOMPARE(replyAnnotation->boundingRectangle(), rootAnnotation->boundingRectangle());
    QCOMPARE(static_cast<Okular::TextAnnotation *>(replyAnnotation)->textIcon(), QStringLiteral("Comment"));
    QVERIFY(!(rootAnnotation->flags() & Okular::Annotation::Hidden));
    QVERIFY(replyAnnotation->flags() & Okular::Annotation::Hidden);

    QTRY_COMPARE_WITH_TIMEOUT(DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("replies"), nullptr, nullptr).size(), 2, 3000);
    QString error;
    const QList<QJsonObject> visible = DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("replies"), nullptr, &error);
    QVERIFY2(error.isEmpty(), qPrintable(error));
    const auto replyRecord = std::find_if(visible.cbegin(), visible.cend(), [&replyId](const QJsonObject &record) { return record.value(QStringLiteral("id")).toString() == replyId; });
    QVERIFY(replyRecord != visible.cend());
    QCOMPARE(replyRecord->value(QStringLiteral("in_reply_to")).toString(), QStringLiteral("reply-root"));
    QCOMPARE(replyRecord->value(QStringLiteral("created_in_app")).toString(), QStringLiteral("thoughts"));
    QVERIFY(replyRecord->value(QStringLiteral("flags")).toInt() & 2);

    QVERIFY(part.openReviewAnnotation(QStringLiteral("reply-root"), 1));
    QTRY_COMPARE_WITH_TIMEOUT(part.m_pageView->findChildren<QFrame *>(QStringLiteral("AnnotWindow")).size(), 1, 1000);
    QFrame *window = part.m_pageView->findChild<QFrame *>(QStringLiteral("AnnotWindow"));
    QVERIFY(window);
    QPushButton *replyButton = window->findChild<QPushButton *>(QStringLiteral("annotationReply"));
    QVERIFY(replyButton);
    QVERIFY(replyButton->isEnabled());
    const QList<QLabel *> threadContents = window->findChildren<QLabel *>(QStringLiteral("annotationThreadContent"));
    QCOMPARE(threadContents.size(), 1);
    QCOMPARE(threadContents.at(0)->text(), QStringLiteral("Desktop reply"));

    AnnotationPopup popup(part.m_document, AnnotationPopup::SingleAnnotationMode, part.widget());
    popup.addAnnotation(rootAnnotation, 0);
    QMenu menu;
    popup.addActionsToMenu(&menu);
    QAction *replyAction = menu.findChild<QAction *>(QStringLiteral("ReplyToAnnotation"));
    QVERIFY(replyAction);
    QVERIFY(replyAction->isEnabled());
    qRegisterMetaType<Okular::Annotation *>();
    QSignalSpy replyRequested(&popup, &AnnotationPopup::replyToAnnotation);
    replyAction->trigger();
    QCOMPARE(replyRequested.size(), 1);
    QCOMPARE(qvariant_cast<Okular::Annotation *>(replyRequested.constFirst().at(0)), rootAnnotation);
    QCOMPARE(replyRequested.constFirst().at(1).toInt(), 0);

    part.m_document->undo();
    QTRY_COMPARE_WITH_TIMEOUT(DocsCommentSynchronizer::visibleSidecarComments(docsRoot.path(), QStringLiteral("replies"), nullptr, nullptr).size(), 1, 3000);
    QVERIFY(!part.m_document->page(0)->annotation(replyId));
    QVERIFY(!part.isModified());
}

